["Chains artık daha fazla silah için yere ve çalışırken kullanabileceği daha iyi bir aydınlatmaya sahip. Burada harika işler çıkacak."] = "CHAINS ARTIK DAHA FAZLA SİLAH İÇİN YERE VE ÇALIŞIRKEN KULLANABİLECEĞİ DAHA İYİ BİR AYDINLATMAYA SAHİP. BURADA HARİKA İŞLER ÇIKACAK.",
["Chains bakmazken Dragan aynaya bir göz attı. Bundan sonra ne olursa olsun kendisini ve çetenin geri kalanını formda tutacak. Bunun için bir spor salonu kuruyor."] = "CHAINS BAKMAZKEN DRAGAN AYNAYA BİR GÖZ ATTI. BUNDAN SONRA NE OLURSA OLSUN KENDİSİNİ VE ÇETENİN GERİ KALANINI FORMDA TUTACAK. BUNUN İÇİN BİR SPOR SALONU KURUYOR.",
["Chains bu bereyi Batı Afrika’daki bir paralı asker operasyonuna hazırlanırken özel yaptırdı. Ama onu takarken neler yaptığını anlatmıyor."] = "CHAINS BU BEREYİ BATI AFRİKA’DAKİ BİR PARALI ASKER OPERASYONUNA HAZIRLANIRKEN ÖZEL YAPTIRDI. AMA ONU TAKARKEN NELER YAPTIĞINI ANLATMIYOR.",
["Chains eskiden askerdi ama oraya uyum sağlayamadı. Banka soygunculuğuna ise doğuştan yetenekli."] = "CHAINS ESKİDEN ASKERDİ AMA ORAYA UYUM SAĞLAYAMADI. BANKA SOYGUNCULUĞUNA İSE DOĞUŞTAN YETENEKLİ.",
["Chains genellikle kurşun işlemezmiş gibi davranıp konuşur. Belki de öyledir."] = "CHAINS GENELLİKLE KURŞUN İŞLEMEZMİŞ GİBİ DAVRANIP KONUŞUR. BELKİ DE ÖYLEDİR.",
