["Clover Character Pack DLC içeriğini hemen satın al!"] = "CLOVER CHARACTER PACK DLC İÇERİĞİNİ HEMEN SATIN AL!",
["Clover elektroniğe servet harcıyor."] = "CLOVER ELEKTRONİĞE SERVET HARCIYOR.",
["Clover evi baskın ve sızmalardan koruyacak bir güvenlik sistemi kurmaya çalışıyor. Güvenli Evi gerçekten güvenli yapacak."] = "CLOVER EVİ BASKIN VE SIZMALARDAN KORUYACAK BİR GÜVENLİK SİSTEMİ KURMAYA ÇALIŞIYOR. GÜVENLİ EVİ GERÇEKTEN GÜVENLİ YAPACAK.",
["Clover ile Hoxton’ın, Payday Gang’den öncesine uzanan uzun ve karmaşık bir ilişkisi var. Ama artık iyi anlaşıyorlar."] = "CLOVER İLE HOXTON’IN, PAYDAY GANG’DEN ÖNCESİNE UZANAN UZUN VE KARMAŞIK BİR İLİŞKİSİ VAR. AMA ARTIK İYİ ANLAŞIYORLAR.",
["Clover o gizli kasada ne olduğunu biliyor ve onu istiyor. Onun için al."] = "CLOVER O GİZLİ KASADA NE OLDUĞUNU BİLİYOR VE ONU İSTİYOR. ONUN İÇİN AL.",
["Clover o sandviçi gerçekten istiyor. Hayır, herhangi bir sandviçi değil; onu."] = "CLOVER O SANDVİÇİ GERÇEKTEN İSTİYOR. HAYIR, HERHANGİ BİR SANDVİÇİ DEĞİL; ONU.",
["Clover sonunda buraya düzgün bilgisayarlar yerleştirdi. Dediğine göre güvenlik sistemi nihayet Taş Devri’nden çıkmış."] = "CLOVER SONUNDA BURAYA DÜZGÜN BİLGİSAYARLAR YERLEŞTİRDİ. DEDİĞİNE GÖRE GÜVENLİK SİSTEMİ NİHAYET TAŞ DEVRİ’NDEN ÇIKMIŞ.",
["Clover, The Walking Dead hayranıdır."] = "CLOVER, THE WALKİNG DEAD HAYRANIDIR.",
["Clover, şehrin sert bir mahallesinde, sert bir ailede büyüdü. Ataları her nesilde savaşçıydı ve İrlanda mirasına sıkı sıkıya bağlı. Hem uğur getirsin diye hem de \"İrlandalıyım ve bununla gurur duyuyorum\" demek için yonca takıyor."] = "CLOVER, ŞEHRİN SERT BİR MAHALLESİNDE, SERT BİR AİLEDE BÜYÜDÜ. ATALARI HER NESİLDE SAVAŞÇIYDI VE İRLANDA MİRASINA SIKI SIKIYA BAĞLI. HEM UĞUR GETİRSİN DİYE HEM DE \"İRLANDALIYIM VE BUNUNLA GURUR DUYUYORUM\" DEMEK İÇİN YONCA TAKIYOR.",
["Clover’ın Gözetleme Merkezi"] = "CLOVER’IN GÖZETLEME MERKEZİ",
["Clover’ın adı şanslı bir soyguncu olmasına gönderme yapar. Gerçekten de şanslıdır."] = "CLOVER’IN ADI ŞANSLI BİR SOYGUNCU OLMASINA GÖNDERME YAPAR. GERÇEKTEN DE ŞANSLIDIR.",
["Clover’ın maskesi, Clover’ın hem en çok korktuğu hem de en çok nefret ettiği şeyi temsil ediyor: Normal yüzün olarak maske takmak. Ameliyatla küçültülmüş burun, botokslu dudaklar, her şeyi yutan kibir ve kendine hayranlık ifadesi; hepsi korkunun ve zayıflığın, korkunç bir parodiye dönüştürülmüş simgeleri."] = "CLOVER’IN MASKESİ, CLOVER’IN HEM EN ÇOK KORKTUĞU HEM DE EN ÇOK NEFRET ETTİĞİ ŞEYİ TEMSİL EDİYOR: NORMAL YÜZÜN OLARAK MASKE TAKMAK. AMELİYATLA KÜÇÜLTÜLMÜŞ BURUN, BOTOKSLU DUDAKLAR, HER ŞEYİ YUTAN KİBİR VE KENDİNE HAYRANLIK İFADESİ; HEPSİ KORKUNUN VE ZAYIFLIĞIN, KORKUNÇ BİR PARODİYE DÖNÜŞTÜRÜLMÜŞ SİMGELERİ.",
["Cobra Hafif Makineli Silahı"] = "COBRA HAFİF MAKİNELİ SİLAHI",
["Colin Powell'dan alıntı yapayım: Başarının sırrı yoktur. Hazırlığın, çok çalışmanın ve başarısızlıktan ders almanın sonucudur."] = "COLİN POWELL'DAN ALINTI YAPAYIM: BAŞARININ SIRRI YOKTUR. HAZIRLIĞIN, ÇOK ÇALIŞMANIN VE BAŞARISIZLIKTAN DERS ALMANIN SONUCUDUR.",
["Commander Wasp inanılmaz teknik kapasiteye sahipti. Gücü ve zekâsı karşı tarafı açık ara geride bırakıyordu. Düşman kuvvetlerini zekâsıyla alt edecek devrelere sahip bir prototipti. Ama denenmemiş bir prototip. Aceleye gelmiş. Fazla deneysel. Delilik devre kartlarına da vurur ama biz ona \"hata\" deriz. Bir paranoya nöbetinde kendi askerlerini öldüren Commander Wasp, savaş suçlusuna dönüştü."] = "COMMANDER WASP İNANILMAZ TEKNİK KAPASİTEYE SAHİPTİ. GÜCÜ VE ZEKÂSI KARŞI TARAFI AÇIK ARA GERİDE BIRAKIYORDU. DÜŞMAN KUVVETLERİNİ ZEKÂSIYLA ALT EDECEK DEVRELERE SAHİP BİR PROTOTİPTİ. AMA DENENMEMİŞ BİR PROTOTİP. ACELEYE GELMİŞ. FAZLA DENEYSEL. DELİLİK DEVRE KARTLARINA DA VURUR AMA BİZ ONA \"HATA\" DERİZ. BİR PARANOYA NÖBETİNDE KENDİ ASKERLERİNİ ÖLDÜREN COMMANDER WASP, SAVAŞ SUÇLUSUNA DÖNÜŞTÜ.",
["Commando 101 Roketatarı"] = "COMMANDO 101 ROKETATARI",
["Commando 553 Tüfeği"] = "COMMANDO 553 TÜFEĞİ",
["Commissar Downtown'da saklanıyor. Buna dair bir ipucu arayın. Downtown'da."] = "COMMİSSAR DOWNTOWN'DA SAKLANIYOR. BUNA DAİR BİR İPUCU ARAYIN. DOWNTOWN'DA.",
["Commissar Foggy Bottom civarında bir yere sığınmış. Orayla ilgili ipucu bulun."] = "COMMİSSAR FOGGY BOTTOM CİVARINDA BİR YERE SIĞINMIŞ. ORAYLA İLGİLİ İPUCU BULUN.",
["Commissar Georgetown civarında bir yere saklanmış. İpucu bulun. Georgetown'la ilgili bir şey."] = "COMMİSSAR GEORGETOWN CİVARINDA BİR YERE SAKLANMIŞ. İPUCU BULUN. GEORGETOWN'LA İLGİLİ BİR ŞEY.",
["Commissar acımasız bir piç olarak bilinir. Adam kaçırma, işkence ve infaz onun alışıldık yöntemleridir. Etrafta birkaç rehine görmeniz olası."] = "COMMİSSAR ACIMASIZ BİR PİÇ OLARAK BİLİNİR. ADAM KAÇIRMA, İŞKENCE VE İNFAZ ONUN ALIŞILDIK YÖNTEMLERİDİR. ETRAFTA BİRKAÇ REHİNE GÖRMENİZ OLASI.",
["Commissar ağır silahları çağırdı. Hem de çok ağır silahları. O helikopterden uzak durun!"] = "COMMİSSAR AĞIR SİLAHLARI ÇAĞIRDI. HEM DE ÇOK AĞIR SİLAHLARI. O HELİKOPTERDEN UZAK DURUN!",
["Commissar belli ki 'benim olamıyorsa kimsenin olmasın' diyor. Köşeye sıkıştı, adamlarına dağ gibi kokaini tuvaletlere döktürüyor! Acele edip durdurun, kokain sizin olsun!"] = "COMMİSSAR BELLİ Kİ 'BENİM OLAMIYORSA KİMSENİN OLMASIN' DİYOR. KÖŞEYE SIKIŞTI, ADAMLARINA DAĞ GİBİ KOKAİNİ TUVALETLERE DÖKTÜRÜYOR! ACELE EDİP DURDURUN, KOKAİN SİZİN OLSUN!",
["Commissar bir şey mi çeviriyor? O yangınları söndürün!"] = "COMMİSSAR BİR ŞEY Mİ ÇEVİRİYOR? O YANGINLARI SÖNDÜRÜN!",
["Commissar bu odada ne çeviriyor lan?"] = "COMMİSSAR BU ODADA NE ÇEVİRİYOR LAN?",
["Commissar bu odalara epey ruble harcamış gibi. Dağıtın ortalığı! Değerli ne varsa almayı da unutmayın."] = "COMMİSSAR BU ODALARA EPEY RUBLE HARCAMIŞ GİBİ. DAĞITIN ORTALIĞI! DEĞERLİ NE VARSA ALMAYI DA UNUTMAYIN.",
["Commissar bu şeyi Vlad'dan almış galiba. Ağır aksak Rus hurdası..."] = "COMMİSSAR BU ŞEYİ VLAD'DAN ALMIŞ GALİBA. AĞIR AKSAK RUS HURDASI...",
["Commissar elinde kalan her şeyi yolluyor! Lanet saldırı helikopterini bile! Mesafenizi koruyun!"] = "COMMİSSAR ELİNDE KALAN HER ŞEYİ YOLLUYOR! LANET SALDIRI HELİKOPTERİNİ BİLE! MESAFENİZİ KORUYUN!",
["Commissar kene gibi yapışmış saklanıyor. Burası onun işlerinden biri. Ortalığı dağıtın. Bu çöplüğe yeterince zarar verirseniz bizi arar. Ben de izini sürerim."] = "COMMİSSAR KENE GİBİ YAPIŞMIŞ SAKLANIYOR. BURASI ONUN İŞLERİNDEN BİRİ. ORTALIĞI DAĞITIN. BU ÇÖPLÜĞE YETERİNCE ZARAR VERİRSENİZ BİZİ ARAR. BEN DE İZİNİ SÜRERİM.",
["Commissar köhne bir apartmana sığınmış. Sizi gizlice sokacağız ama yine de ortalık karışacak. Yola çıkın."] = "COMMİSSAR KÖHNE BİR APARTMANA SIĞINMIŞ. SİZİ GİZLİCE SOKACAĞIZ AMA YİNE DE ORTALIK KARIŞACAK. YOLA ÇIKIN.",
["Commissar küçük tavuklarını göndermiş. Sıcak karşılayın."] = "COMMİSSAR KÜÇÜK TAVUKLARINI GÖNDERMİŞ. SICAK KARŞILAYIN.",
["Commissar motel saldırısından sonra huzursuzdur ama bunu beklemeyecek. Maskeleri takıp köstebeğe hak ettiğini verin. İyi şanslar."] = "COMMİSSAR MOTEL SALDIRISINDAN SONRA HUZURSUZDUR AMA BUNU BEKLEMEYECEK. MASKELERİ TAKIP KÖSTEBEĞE HAK ETTİĞİNİ VERİN. İYİ ŞANSLAR.",
["Commissar öldü. Böylece Bölge Savcısı da avucumda. Dostunuzun serbest kalmasına bir adım daha yaklaştınız. Haberleşeceğiz."] = "COMMİSSAR ÖLDÜ. BÖYLECE BÖLGE SAVCISI DA AVUCUMDA. DOSTUNUZUN SERBEST KALMASINA BİR ADIM DAHA YAKLAŞTINIZ. HABERLEŞECEĞİZ.",
["Commissar özel hattan Bain’i arayacak. Bain böylece konumunu izleyip tam olarak nerede saklandığını bulabilir."] = "COMMİSSAR ÖZEL HATTAN BAIN’İ ARAYACAK. BAIN BÖYLECE KONUMUNU İZLEYİP TAM OLARAK NEREDE SAKLANDIĞINI BULABİLİR.",
["Commissar! Yakalayın!"] = "COMMİSSAR! YAKALAYIN!",
["Commissar'a ulaşmak için onu bulmalıyız. Bu motel onun işlerinden biri. Verebildiğiniz kadar zarar verin. Ararsa izini sürerim."] = "COMMİSSAR'A ULAŞMAK İÇİN ONU BULMALIYIZ. BU MOTEL ONUN İŞLERİNDEN BİRİ. VEREBİLDİĞİNİZ KADAR ZARAR VERİN. ARARSA İZİNİ SÜRERİM.",
["Commissar'ı alamazsınız!"] = "COMMİSSAR'I ALAMAZSINIZ!",
["Commissar'ı tahta kutuya koymalıyız, kendimiz içinde kalmamalıyız. İlerleyin!"] = "COMMİSSAR'I TAHTA KUTUYA KOYMALIYIZ, KENDİMİZ İÇİNDE KALMAMALIYIZ. İLERLEYİN!",
["Commissar'ı yakalamak için dairelerde savaşarak ilerle!"] = "COMMİSSAR'I YAKALAMAK İÇİN DAİRELERDE SAVAŞARAK İLERLE!",
["Commissar'ı öldür"] = "COMMİSSAR'I ÖLDÜR",
["Commissar'ın Foggy Bottom civarında olduğunu biliyoruz. Orada yerini daraltacak bir şey olmalı. Harita, dosya, ne olursa. "] = "COMMİSSAR'IN FOGGY BOTTOM CİVARINDA OLDUĞUNU BİLİYORUZ. ORADA YERİNİ DARALTACAK BİR ŞEY OLMALI. HARİTA, DOSYA, NE OLURSA. ",
["Commissar'ın adamları yangın sigortası yaptıran tiplere benzemiyor."] = "COMMİSSAR'IN ADAMLARI YANGIN SİGORTASI YAPTIRAN TİPLERE BENZEMİYOR.",
["Commissar'ın adamlarında fena arabalar var. Biraz daha kızdırsak mı onları? Benzin istasyonuna bakın, yakacak bir şey olmalı."] = "COMMİSSAR'IN ADAMLARINDA FENA ARABALAR VAR. BİRAZ DAHA KIZDIRSAK MI ONLARI? BENZİN İSTASYONUNA BAKIN, YAKACAK BİR ŞEY OLMALI.",
["Commissar'ın bizi Georgetown'dan aradığını biliyoruz. O yerle ilgili bir şey arayın. Georgetown."] = "COMMİSSAR'IN BİZİ GEORGETOWN'DAN ARADIĞINI BİLİYORUZ. O YERLE İLGİLİ BİR ŞEY ARAYIN. GEORGETOWN.",
["Commissar'ın bizi araması için hasar vermelisiniz. Odaları dağıtın, arabaları yakın, adamlarını öldürün. Bu dikkatini çeker."] = "COMMİSSAR'IN BİZİ ARAMASI İÇİN HASAR VERMELİSİNİZ. ODALARI DAĞITIN, ARABALARI YAKIN, ADAMLARINI ÖLDÜRÜN. BU DİKKATİNİ ÇEKER.",
["Commissar'ın bu döküntüye yangın ve hasar sigortası yaptırmadığına eminim. O yüzden coşun. Odaları dağıtın, arabaları yakın; o herifi kızdırıp telefona getirmek için ne gerekiyorsa yapın."] = "COMMİSSAR'IN BU DÖKÜNTÜYE YANGIN VE HASAR SİGORTASI YAPTIRMADIĞINA EMİNİM. O YÜZDEN COŞUN. ODALARI DAĞITIN, ARABALARI YAKIN; O HERİFİ KIZDIRIP TELEFONA GETİRMEK İÇİN NE GEREKİYORSA YAPIN.",
["Commissar'ın bütün şu kanlı parasına bakın. Neyse, birinin keyfini sürmesi gerek. Yapabilirseniz helikoptere götürün."] = "COMMİSSAR'IN BÜTÜN ŞU KANLI PARASINA BAKIN. NEYSE, BİRİNİN KEYFİNİ SÜRMESİ GEREK. YAPABİLİRSENİZ HELİKOPTERE GÖTÜRÜN.",
["Commissar'ın hakkını verelim. Kapakta ucuza kaçmamış. Kamyonet sağlam çekiyor."] = "COMMİSSAR'IN HAKKINI VERELİM. KAPAKTA UCUZA KAÇMAMIŞ. KAMYONET SAĞLAM ÇEKİYOR.",
["Commissar'ın işini bitir."] = "COMMİSSAR'IN İŞİNİ BİTİR.",
["Commissar'ın metamfetamin laboratuvarı var! Geçmişte birkaç laboratuvar yaktığınızı biliyorum. Vaktiniz olduğunu düşünüyor ve bir tarif bulabiliyorsanız biraz sihir de pişirebilirsiniz."] = "COMMİSSAR'IN METAMFETAMİN LABORATUVARI VAR! GEÇMİŞTE BİRKAÇ LABORATUVAR YAKTIĞINIZI BİLİYORUM. VAKTİNİZ OLDUĞUNU DÜŞÜNÜYOR VE BİR TARİF BULABİLİYORSANIZ BİRAZ SİHİR DE PİŞİREBİLİRSİNİZ.",
["Commissar'ın yerine sandıklarla giriyoruz. Truva atı usulü. Dairesi, şehrin berbat bir bölgesindeki pis bir döküntü. Güvenlik iyi değil ama onun ve kaslı adamlarının bir numara sakladığına eminim. Hedef basit: Commissar'ı bul ve öldür. Gürültülü olacak; etkileyici biçimde kuşanın."] = "COMMİSSAR'IN YERİNE SANDIKLARLA GİRİYORUZ. TRUVA ATI USULÜ. DAİRESİ, ŞEHRİN BERBAT BİR BÖLGESİNDEKİ PİS BİR DÖKÜNTÜ. GÜVENLİK İYİ DEĞİL AMA ONUN VE KASLI ADAMLARININ BİR NUMARA SAKLADIĞINA EMİNİM. HEDEF BASİT: COMMİSSAR'I BUL VE ÖLDÜR. GÜRÜLTÜLÜ OLACAK; ETKİLEYİCİ BİÇİMDE KUŞANIN.",
["Commissar'ın çocukları buraya hamam böceği gibi üşüşmüş. Odalara yuvalanmadan yok edin."] = "COMMİSSAR'IN ÇOCUKLARI BURAYA HAMAM BÖCEĞİ GİBİ ÜŞÜŞMÜŞ. ODALARA YUVALANMADAN YOK EDİN.",
