["Dost Ateşi Hasar Çarpanı"] = "DOST ATEŞİ HASAR ÇARPANI",
["Dost Ateşi değiştiricisi açıkken herhangi bir soygunu DEATH WISH veya üzeri zorlukta başka bir oyuncuya zarar vermeden tamamla. Bu kupa için soygunda dört oyuncu bulunmalı."] = "DOST ATEŞİ DEĞİŞTİRİCİSİ AÇIKKEN HERHANGİ BİR SOYGUNU DEATH WISH VEYA ÜZERİ ZORLUKTA BAŞKA BİR OYUNCUYA ZARAR VERMEDEN TAMAMLA. BU KUPA İÇİN SOYGUNDA DÖRT OYUNCU BULUNMALI.",
["Dost Düşmanlarına İyi Bak"] = "DOST DÜŞMANLARINA İYİ BAK",
["Dost canlısı herifimizi takip edin yeter. Gerçeklerine görünmeyin."] = "DOST CANLISI HERİFİMİZİ TAKİP EDİN YETER. GERÇEKLERİNE GÖRÜNMEYİN.",
["Dostane Sızma"] = "DOSTANE SIZMA",
["Dostlar! Ben Locke. Alaska'dan sonra bana güvenmek için pek sebebiniz olmadığını biliyorum ama sizi DC'den çıkarmak için o kısıtlı zamanda kurabileceğimiz tek inandırıcı oyun buydu. Bain'in eskiden güvenilir sandığı insanlar... bizi dinliyordu. Şimdi de o kayıp... Bir şey olacağını biliyorduk ama ne zaman ya da ne olacağını bilmiyorduk. Sizi habersiz bırakma kararı Bain'in değil, benimdi. Gerçekten ona ulaşabileceklerini hiç düşünmemiştim. Bakın, bunları duymak boktan, biliyorum ama bıraktığım silahlarla çıktınız, değil mi? Bain için üzgünüm... Bunu halledeceğiz... ama önce sizi oradan çıkarmamız gerekiyor. Lütfen bana güvenin millet, sizi kandırmıyorum. Bunu kanıtlayacağıma söz veriyorum."] = "DOSTLAR! BEN LOCKE. ALASKA'DAN SONRA BANA GÜVENMEK İÇİN PEK SEBEBİNİZ OLMADIĞINI BİLİYORUM AMA SİZİ DC'DEN ÇIKARMAK İÇİN O KISITLI ZAMANDA KURABİLECEĞİMİZ TEK İNANDIRICI OYUN BUYDU. BAIN'İN ESKİDEN GÜVENİLİR SANDIĞI İNSANLAR... BİZİ DİNLİYORDU. ŞİMDİ DE O KAYIP... BİR ŞEY OLACAĞINI BİLİYORDUK AMA NE ZAMAN YA DA NE OLACAĞINI BİLMİYORDUK. SİZİ HABERSİZ BIRAKMA KARARI BAIN'İN DEĞİL, BENİMDİ. GERÇEKTEN ONA ULAŞABİLECEKLERİNİ HİÇ DÜŞÜNMEMİŞTİM. BAKIN, BUNLARI DUYMAK BOKTAN, BİLİYORUM AMA BIRAKTIĞIM SİLAHLARLA ÇIKTINIZ, DEĞİL Mİ? BAIN İÇİN ÜZGÜNÜM... BUNU HALLEDECEĞİZ... AMA ÖNCE SİZİ ORADAN ÇIKARMAMIZ GEREKİYOR. LÜTFEN BANA GÜVENİN MİLLET, SİZİ KANDIRMIYORUM. BUNU KANITLAYACAĞIMA SÖZ VERİYORUM.",
["Dostlar! Black Ridge'e hoş geldiniz. Çok gizli! Söyleyebileceğim tek şey burada ganimet olduğu. Çok değerli ganimet."] = "DOSTLAR! BLACK RİDGE'E HOŞ GELDİNİZ. ÇOK GİZLİ! SÖYLEYEBİLECEĞİM TEK ŞEY BURADA GANİMET OLDUĞU. ÇOK DEĞERLİ GANİMET.",
["Dostlar! Buradayım ve yerimi aldım! Lütfen fırsat bulduğunuzda kayışları alıp şu muhteşem para yığınına bağlayın."] = "DOSTLAR! BURADAYIM VE YERİMİ ALDIM! LÜTFEN FIRSAT BULDUĞUNUZDA KAYIŞLARI ALIP ŞU MUHTEŞEM PARA YIĞININA BAĞLAYIN.",
["Dostlar! Güzel dostlar! Uçuş nasıl? Atlayış konumuna yaklaşıyoruz. Lütfen kapağı açın ve..."] = "DOSTLAR! GÜZEL DOSTLAR! UÇUŞ NASIL? ATLAYIŞ KONUMUNA YAKLAŞIYORUZ. LÜTFEN KAPAĞI AÇIN VE...",
["Dostlar, Elephant bana biraz istihbarat sağladı ve Bain'in yerini buldum. Kataru aptalları onu İkinci Dünya Savaşı'ndan kalma terk edilmiş bir hapishanede tutuyor. Tesis, Oregon'un kuzey kıyısı açıklarında, uluslararası sulardaki bir adada. Murky'ler 70'lerden beri kullanıyor. Birkaç kişiden ricada bulunup size küçük bir sivil denizaltıda yer ayarladım. Böylece gizlice girip adamımızı geri alabilirsiniz."] = "DOSTLAR, ELEPHANT BANA BİRAZ İSTİHBARAT SAĞLADI VE BAIN'İN YERİNİ BULDUM. KATARU APTALLARI ONU İKİNCİ DÜNYA SAVAŞI'NDAN KALMA TERK EDİLMİŞ BİR HAPİSHANEDE TUTUYOR. TESİS, OREGON'UN KUZEY KIYISI AÇIKLARINDA, ULUSLARARASI SULARDAKİ BİR ADADA. MURKY'LER 70'LERDEN BERİ KULLANIYOR. BİRKAÇ KİŞİDEN RİCADA BULUNUP SİZE KÜÇÜK BİR SİVİL DENİZALTIDA YER AYARLADIM. BÖYLECE GİZLİCE GİRİP ADAMIMIZI GERİ ALABİLİRSİNİZ.",
["Dostlar, Triad'larla kapışarak risk alıyoruz ama sağlam bir iş bu. Jiu Feng konum hakkında harika ayrıntılar verdi; Chinatown'a gidiyoruz! Heykel, paravan bir çay dükkânının arkasındaki depoda tutuluyor. Birkaç güvenlik sistemini aşmalısınız. Triad diğer değerli eşyalarından bazılarını zengin ahmaklara açık artırmayla satıyor; sivillerin dikkatini dağıtmaya hazır olun. Minibüsün frenlerinin iyi durumda olduğundan emin olun. Bir de bana köşedeki Chao's restoranından Çin böreği getirin; batı kıyısının en iyi Çin yemeği oradaymış, kesin!"] = "DOSTLAR, TRİAD'LARLA KAPIŞARAK RİSK ALIYORUZ AMA SAĞLAM BİR İŞ BU. JIU FENG KONUM HAKKINDA HARİKA AYRINTILAR VERDİ; CHİNATOWN'A GİDİYORUZ! HEYKEL, PARAVAN BİR ÇAY DÜKKÂNININ ARKASINDAKİ DEPODA TUTULUYOR. BİRKAÇ GÜVENLİK SİSTEMİNİ AŞMALISINIZ. TRİAD DİĞER DEĞERLİ EŞYALARINDAN BAZILARINI ZENGİN AHMAKLARA AÇIK ARTIRMAYLA SATIYOR; SİVİLLERİN DİKKATİNİ DAĞITMAYA HAZIR OLUN. MİNİBÜSÜN FRENLERİNİN İYİ DURUMDA OLDUĞUNDAN EMİN OLUN. BİR DE BANA KÖŞEDEKİ CHAO'S RESTORANINDAN ÇİN BÖREĞİ GETİRİN; BATI KIYISININ EN İYİ ÇİN YEMEĞİ ORADAYMIŞ, KESİN!",
["Dostlar, Twitch minibüsle birazdan orada!"] = "DOSTLAR, TWITCH MİNİBÜSLE BİRAZDAN ORADA!",
["Dostlar, Vlad biraz sabırsızlanıyor..."] = "DOSTLAR, VLAD BİRAZ SABIRSIZLANIYOR...",
["Dostlar, asansörle aşağı inerken duvarlar üstünüze geliyormuş gibi hissettiğiniz oluyor mu? "] = "DOSTLAR, ASANSÖRLE AŞAĞI İNERKEN DUVARLAR ÜSTÜNÜZE GELİYORMUŞ GİBİ HİSSETTİĞİNİZ OLUYOR MU? ",
["Dostlar, az önce yanından geçtiğiniz C4 müydü? Belki buradan daha hızlı çıkış açmak için kullanırsınız."] = "DOSTLAR, AZ ÖNCE YANINDAN GEÇTİĞİNİZ C4 MÜYDÜ? BELKİ BURADAN DAHA HIZLI ÇIKIŞ AÇMAK İÇİN KULLANIRSINIZ.",
["Dostlar, aşçılığınızı yarıda kestiler, öyle mi? Yeniden yapmanız gerek!"] = "DOSTLAR, AŞÇILIĞINIZI YARIDA KESTİLER, ÖYLE Mİ? YENİDEN YAPMANIZ GEREK!",
["Dostlar, bana hâlâ güvenmediğinizi biliyorum ama polislerden kurtulunca daha çok konuşuruz, tamam mı?"] = "DOSTLAR, BANA HÂLÂ GÜVENMEDİĞİNİZİ BİLİYORUM AMA POLİSLERDEN KURTULUNCA DAHA ÇOK KONUŞURUZ, TAMAM MI?",
["Dostlar, başka bir rehine işinin zamanı geldi; bu kez Meksika'dayız. Bu küçük kasaba bankası, polisleri püskürtüp fidyenin büyümesini izlemek için mükemmel. Rehineyi gözden kaçırmayın ve dayanabildiğiniz kadar mevzinizi koruyun."] = "DOSTLAR, BAŞKA BİR REHİNE İŞİNİN ZAMANI GELDİ; BU KEZ MEKSİKA'DAYIZ. BU KÜÇÜK KASABA BANKASI, POLİSLERİ PÜSKÜRTÜP FİDYENİN BÜYÜMESİNİ İZLEMEK İÇİN MÜKEMMEL. REHİNEYİ GÖZDEN KAÇIRMAYIN VE DAYANABİLDİĞİNİZ KADAR MEVZİNİZİ KORUYUN.",
["Dostlar, beni ana bilgisayara bağlayın, çabuk!"] = "DOSTLAR, BENİ ANA BİLGİSAYARA BAĞLAYIN, ÇABUK!",
["Dostlar, beni ana bilgisayara bağlayın."] = "DOSTLAR, BENİ ANA BİLGİSAYARA BAĞLAYIN.",
["Dostlar, bir silah anlaşmasında bana yardım etmeye ne dersiniz?"] = "DOSTLAR, BİR SİLAH ANLAŞMASINDA BANA YARDIM ETMEYE NE DERSİNİZ?",
["Dostlar, bu başarısız olma lüksümüzün olmadığı bir işti. İyi değil. Hiç iyi değil."] = "DOSTLAR, BU BAŞARISIZ OLMA LÜKSÜMÜZÜN OLMADIĞI BİR İŞTİ. İYİ DEĞİL. HİÇ İYİ DEĞİL.",
["Dostlar, bu kattaki kapılardan birine testere kurun, tamam mı?"] = "DOSTLAR, BU KATTAKİ KAPILARDAN BİRİNE TESTERE KURUN, TAMAM MI?",
["Dostlar, bölgede Murkywater ajanları var. Bizi nasıl buldular? "] = "DOSTLAR, BÖLGEDE MURKYWATER AJANLARI VAR. BİZİ NASIL BULDULAR? ",
["Dostlar, bütün ganimeti yakında bir yere yığsanız iyi olur. Sonra taşıyabilirsiniz, tamam mı?"] = "DOSTLAR, BÜTÜN GANİMETİ YAKINDA BİR YERE YIĞSANIZ İYİ OLUR. SONRA TAŞIYABİLİRSİNİZ, TAMAM MI?",
["Dostlar, cadılar diyarına bir yolculuğa ne dersiniz? Soyulmayı bekleyen bir müzayede var."] = "DOSTLAR, CADILAR DİYARINA BİR YOLCULUĞA NE DERSİNİZ? SOYULMAYI BEKLEYEN BİR MÜZAYEDE VAR.",
["Dostlar, daha fazla Murky geliyor. Dikkatli olun."] = "DOSTLAR, DAHA FAZLA MURKY GELİYOR. DİKKATLİ OLUN.",
["Dostlar, en azından bu işten iyi bir şey çıkabilir. Gidip o testereyi bulun."] = "DOSTLAR, EN AZINDAN BU İŞTEN İYİ BİR ŞEY ÇIKABİLİR. GİDİP O TESTEREYİ BULUN.",
["Dostlar, en iyisi arka kapıdan testereyle girmek galiba, ha?"] = "DOSTLAR, EN İYİSİ ARKA KAPIDAN TESTEREYLE GİRMEK GALİBA, HA?",
["Dostlar, işe koyulalım, çabuk çabuk. Tesisin sunucu odasını bulun, kamera görüntülerine erişip Vlad'ı tuttukları konteyneri tespit edin. Kontrol odasındaki yük listesiyle doğru şirketi eşleştirirseniz nereye gideceğimizi öğreniriz."] = "DOSTLAR, İŞE KOYULALIM, ÇABUK ÇABUK. TESİSİN SUNUCU ODASINI BULUN, KAMERA GÖRÜNTÜLERİNE ERİŞİP VLAD'I TUTTUKLARI KONTEYNERİ TESPİT EDİN. KONTROL ODASINDAKİ YÜK LİSTESİYLE DOĞRU ŞİRKETİ EŞLEŞTİRİRSENİZ NEREYE GİDECEĞİMİZİ ÖĞRENİRİZ.",
["Dostlar, işe yaradı! İçeri girip af belgelerini alabilirsiniz!"] = "DOSTLAR, İŞE YARADI! İÇERİ GİRİP AF BELGELERİNİ ALABİLİRSİNİZ!",
["Dostlar, masrafları karşılanmış LA gezisine ne dersiniz? Güzel, değil mi?! Bir de hazır oradayken..."] = "DOSTLAR, MASRAFLARI KARŞILANMIŞ LA GEZİSİNE NE DERSİNİZ? GÜZEL, DEĞİL Mİ?! BİR DE HAZIR ORADAYKEN...",
["Dostlar, mini yükleyicinin geçmesi için o konteyneri çekmeniz gerekecek. Etrafta bir yol arayın."] = "DOSTLAR, MİNİ YÜKLEYİCİNİN GEÇMESİ İÇİN O KONTEYNERİ ÇEKMENİZ GEREKECEK. ETRAFTA BİR YOL ARAYIN.",
["Dostlar, o bariyerleri geçmeliyiz ama önce aklımda bir fikir var."] = "DOSTLAR, O BARİYERLERİ GEÇMELİYİZ AMA ÖNCE AKLIMDA BİR FİKİR VAR.",
["Dostlar, o kapıdan geçiş yok. Dışarıdaki iskeleyi kullanıp ikinci kata çıkın. Zeminde zayıf bir yer falan var mı, bakın."] = "DOSTLAR, O KAPIDAN GEÇİŞ YOK. DIŞARIDAKİ İSKELEYİ KULLANIP İKİNCİ KATA ÇIKIN. ZEMİNDE ZAYIF BİR YER FALAN VAR MI, BAKIN.",
["Dostlar, o kasa dairesinin kapısına biraz termit koyun, olur mu?"] = "DOSTLAR, O KASA DAİRESİNİN KAPISINA BİRAZ TERMİT KOYUN, OLUR MU?",
["Dostlar, o matkabı kasa dairesinin bulunduğu odaya getirmeniz gerekecek."] = "DOSTLAR, O MATKABI KASA DAİRESİNİN BULUNDUĞU ODAYA GETİRMENİZ GEREKECEK.",
["Dostlar, oradan çıkma vakti!"] = "DOSTLAR, ORADAN ÇIKMA VAKTİ!",
["Dostlar, oralarda bir sunucu odası olmalı. Bulun da şu kapıyı açalım."] = "DOSTLAR, ORALARDA BİR SUNUCU ODASI OLMALI. BULUN DA ŞU KAPIYI AÇALIM.",
["Dostlar, pencereye ateş edin. Vurun. Şu. Camı!"] = "DOSTLAR, PENCEREYE ATEŞ EDİN. VURUN. ŞU. CAMI!",
["Dostlar, sizi bariyerlerden geçirmeden önce... Aklıma bir fikir geldi."] = "DOSTLAR, SİZİ BARİYERLERDEN GEÇİRMEDEN ÖNCE... AKLIMA BİR FİKİR GELDİ.",
["Dostlar, söz veriyorum; bu işin sonuna kadar yanınızda olacağım, tamam mı? Bain uzun zamandır gizlice bir çeşit Kutsal Kâse gibi bir şey arıyordu. Ben de yardım etmeye kararlıyım. O gitmiş olabilir ama arayış sürecek. Duke, eski bilgilerin ciltlerini karıştırarak bir sürü yeni ipucunu açığa çıkarmaya başladı. Bain kaçırılmadan önce Brooklyn’deki bir bankanın temeline gömülü bir eseri bulmak için plan yaptı. Bu eser 1900’lerin başında oraya konmuş ve ihtiyacımız olan ipuçlarını içeriyor olabilir."] = "DOSTLAR, SÖZ VERİYORUM; BU İŞİN SONUNA KADAR YANINIZDA OLACAĞIM, TAMAM MI? BAIN UZUN ZAMANDIR GİZLİCE BİR ÇEŞİT KUTSAL KÂSE GİBİ BİR ŞEY ARIYORDU. BEN DE YARDIM ETMEYE KARARLIYIM. O GİTMİŞ OLABİLİR AMA ARAYIŞ SÜRECEK. DUKE, ESKİ BİLGİLERİN CİLTLERİNİ KARIŞTIRARAK BİR SÜRÜ YENİ İPUCUNU AÇIĞA ÇIKARMAYA BAŞLADI. BAIN KAÇIRILMADAN ÖNCE BROOKLYN’DEKİ BİR BANKANIN TEMELİNE GÖMÜLÜ BİR ESERİ BULMAK İÇİN PLAN YAPTI. BU ESER 1900’LERİN BAŞINDA ORAYA KONMUŞ VE İHTİYACIMIZ OLAN İPUÇLARINI İÇERİYOR OLABİLİR.",
["Dostlar, tam vaktinde geldiniz. Müzayede henüz başlamadı, konuklar hâlâ etrafta dolaşıyor. Aradığımız eşya malikânenin arkasındaki depo alanında bir Kasa Dairesinde olmalı."] = "DOSTLAR, TAM VAKTİNDE GELDİNİZ. MÜZAYEDE HENÜZ BAŞLAMADI, KONUKLAR HÂLÂ ETRAFTA DOLAŞIYOR. ARADIĞIMIZ EŞYA MALİKÂNENİN ARKASINDAKİ DEPO ALANINDA BİR KASA DAİRESİNDE OLMALI.",
["Dostlar, testereyi yeniden çalıştırmanız gerekiyor."] = "DOSTLAR, TESTEREYİ YENİDEN ÇALIŞTIRMANIZ GEREKİYOR.",
["Dostlar, çölde biraz eğlence ister misiniz? Yağmalanması gereken bir Murky tesisi var."] = "DOSTLAR, ÇÖLDE BİRAZ EĞLENCE İSTER MİSİNİZ? YAĞMALANMASI GEREKEN BİR MURKY TESİSİ VAR.",
["Dostlar, şu balıklı takoların neden bu kadar olay olduğunu anlatmalısınız. Bana sorarsanız berbat geliyor. Köpekbalığı yüzgeci olsa belki..."] = "DOSTLAR, ŞU BALIKLI TAKOLARIN NEDEN BU KADAR OLAY OLDUĞUNU ANLATMALISINIZ. BANA SORARSANIZ BERBAT GELİYOR. KÖPEKBALIĞI YÜZGECİ OLSA BELKİ...",
["Dostlar, şu lanet aracı yoldan çekin, olur mu?"] = "DOSTLAR, ŞU LANET ARACI YOLDAN ÇEKİN, OLUR MU?",
["Dostlar..."] = "DOSTLAR...",
["Dostlar? Dostlar? Duyuyor musunuz? Lanet olsun, o neydi? Neyse..."] = "DOSTLAR? DOSTLAR? DUYUYOR MUSUNUZ? LANET OLSUN, O NEYDİ? NEYSE...",
["Dostlarım! Vlad'ın şu eski dükkânların kasalarını dengelemesine yardım eder misiniz? Küçücük bir iş aslında."] = "DOSTLARIM! VLAD'IN ŞU ESKİ DÜKKÂNLARIN KASALARINI DENGELEMESİNE YARDIM EDER MİSİNİZ? KÜÇÜCÜK BİR İŞ ASLINDA.",
["Dostlarım! Yola devam etmeden önce grubunuzu toplamalısınız."] = "DOSTLARIM! YOLA DEVAM ETMEDEN ÖNCE GRUBUNUZU TOPLAMALISINIZ.",
["Dostlarım! Zevkle!"] = "DOSTLARIM! ZEVKLE!",
["Dostlarım! İndirme noktası olarak seçtiğim yere yaklaşıyoruz. O yüzden daha fazla uzatmadan..."] = "DOSTLARIM! İNDİRME NOKTASI OLARAK SEÇTİĞİM YERE YAKLAŞIYORUZ. O YÜZDEN DAHA FAZLA UZATMADAN...",
["Dostlarım, \"Yola devam etmeden önce grubunuzu toplamalısınız!\""] = "DOSTLARIM, \"YOLA DEVAM ETMEDEN ÖNCE GRUBUNUZU TOPLAMALISINIZ!\"",
["Dostlarım, Noel'imi kurtaracaksınız."] = "DOSTLARIM, NOEL'İMİ KURTARACAKSINIZ.",
["Dostlarım, Vlad'in düğün için mücevher seçerken yardıma ihtiyacı var... Sakıncası yoksa."] = "DOSTLARIM, VLAD'İN DÜĞÜN İÇİN MÜCEVHER SEÇERKEN YARDIMA İHTİYACI VAR... SAKINCASI YOKSA.",
["Dostlarım, Vlad'in düğün planlamasında ufak yardıma ihtiyacı var."] = "DOSTLARIM, VLAD'İN DÜĞÜN PLANLAMASINDA UFAK YARDIMA İHTİYACI VAR.",
["Dostlarım, bence başımıza çok dert açan şu Golden-Toothpick orospu çocuklarından öcümüzü almalıyız, değil mi? Rıhtımda bulduğunuz bilgileri inceledim, daha fazlasını öğrenmek için Gow Fong'la çalıştım. Kabul edeyim, adam işini biliyor! Triad artık parasının çoğunu sahibi oldukları The Black Cat yolcu gemisinin kumarhanesindeki kasa dairesinde tutuyor. Mekânı bana işkence eden piç, Xun Kang yönetiyor bir de! İnanabiliyor musunuz? Girip şu erişte emicilere Titanic'teymiş gibi hissettirsek, bütün paralarını alsak nasıl olur? Patronları o Wong denen göte, yaptıklarının hesabını sorup işini bitireceğime söz verdim. Vlad sözünü tutar. Ben intikamımı alırım, siz denizde güzel tatil yaparsınız, hepimiz de siktiğimin parasından bol bol kazanırız. Nasıl?"] = "DOSTLARIM, BENCE BAŞIMIZA ÇOK DERT AÇAN ŞU GOLDEN-TOOTHPİCK OROSPU ÇOCUKLARINDAN ÖCÜMÜZÜ ALMALIYIZ, DEĞİL Mİ? RIHTIMDA BULDUĞUNUZ BİLGİLERİ İNCELEDİM, DAHA FAZLASINI ÖĞRENMEK İÇİN GOW FONG'LA ÇALIŞTIM. KABUL EDEYİM, ADAM İŞİNİ BİLİYOR! TRİAD ARTIK PARASININ ÇOĞUNU SAHİBİ OLDUKLARI THE BLACK CAT YOLCU GEMİSİNİN KUMARHANESİNDEKİ KASA DAİRESİNDE TUTUYOR. MEKÂNI BANA İŞKENCE EDEN PİÇ, XUN KANG YÖNETİYOR BİR DE! İNANABİLİYOR MUSUNUZ? GİRİP ŞU ERİŞTE EMİCİLERE TİTANİC'TEYMİŞ GİBİ HİSSETTİRSEK, BÜTÜN PARALARINI ALSAK NASIL OLUR? PATRONLARI O WONG DENEN GÖTE, YAPTIKLARININ HESABINI SORUP İŞİNİ BİTİRECEĞİME SÖZ VERDİM. VLAD SÖZÜNÜ TUTAR. BEN İNTİKAMIMI ALIRIM, SİZ DENİZDE GÜZEL TATİL YAPARSINIZ, HEPİMİZ DE SİKTİĞİMİN PARASINDAN BOL BOL KAZANIRIZ. NASIL?",
["Dostlarım, bir Batmanuel pencereden atlayıp yardıma gelmeyecek. O lazerleri kendiniz halletmelisiniz!"] = "DOSTLARIM, BİR BATMANUEL PENCEREDEN ATLAYIP YARDIMA GELMEYECEK. O LAZERLERİ KENDİNİZ HALLETMELİSİNİZ!",
["Dostlarım, biraz alışılmadık bir banka soygunu yapmamız gerek, ha?"] = "DOSTLARIM, BİRAZ ALIŞILMADIK BİR BANKA SOYGUNU YAPMAMIZ GEREK, HA?",
["Dostlarım, bırakın zaman kilidi tik tak etsin, olur mu? Sabrınızın karşılığını alacaksınız."] = "DOSTLARIM, BIRAKIN ZAMAN KİLİDİ TİK TAK ETSİN, OLUR MU? SABRINIZIN KARŞILIĞINI ALACAKSINIZ.",
["Dostlarım, diğer bilgisayarı bulup güvenlik duvarını kapatın."] = "DOSTLARIM, DİĞER BİLGİSAYARI BULUP GÜVENLİK DUVARINI KAPATIN.",
["Dostlarım, hâlâ çözmeye çalışıyorum. Dayanın."] = "DOSTLARIM, HÂLÂ ÇÖZMEYE ÇALIŞIYORUM. DAYANIN.",
["Dostlarım, iş ciddi biliyorum ama biraz da eğlenmek gerek, değil mi? Şimdi izleyin!"] = "DOSTLARIM, İŞ CİDDİ BİLİYORUM AMA BİRAZ DA EĞLENMEK GEREK, DEĞİL Mİ? ŞİMDİ İZLEYİN!",
["Dostlarım, kamyondan zinciri alıp gişe penceresine bağlayın!"] = "DOSTLARIM, KAMYONDAN ZİNCİRİ ALIP GİŞE PENCERESİNE BAĞLAYIN!",
["Dostlarım, kanun bize yetişmeden kokainimizi DC'den hızla çıkarmamız gerekiyor. Siz sigorta ekibi olacaksınız."] = "DOSTLARIM, KANUN BİZE YETİŞMEDEN KOKAİNİMİZİ DC'DEN HIZLA ÇIKARMAMIZ GEREKİYOR. SİZ SİGORTA EKİBİ OLACAKSINIZ.",
["Dostlarım, küçük bir sorunda yardım eder misiniz? Bir... aile sorunu çıkarmanız gerek."] = "DOSTLARIM, KÜÇÜK BİR SORUNDA YARDIM EDER MİSİNİZ? BİR... AİLE SORUNU ÇIKARMANIZ GEREK.",
["Dostlarım, o Rus için ne diye çalışıyorsunuz? Beni bırakın. Karşılığını alırsınız."] = "DOSTLARIM, O RUS İÇİN NE DİYE ÇALIŞIYORSUNUZ? BENİ BIRAKIN. KARŞILIĞINI ALIRSINIZ.",
["Dostlarım, sizi bekliyorum!"] = "DOSTLARIM, SİZİ BEKLİYORUM!",
["Dostlarım. Size ufak bir Los Angeles gezisi ısmarlamak istiyorum. Belki orada benim için ufak bir iş yaparsınız, olur mu?"] = "DOSTLARIM. SİZE UFAK BİR LOS ANGELES GEZİSİ ISMARLAMAK İSTİYORUM. BELKİ ORADA BENİM İÇİN UFAK BİR İŞ YAPARSINIZ, OLUR MU?",
["Dostlarımız aletleri bir minibüse sakladı. Asansör boşluğuna ulaşmak için onları bulun."] = "DOSTLARIMIZ ALETLERİ BİR MİNİBÜSE SAKLADI. ASANSÖR BOŞLUĞUNA ULAŞMAK İÇİN ONLARI BULUN.",
["Dostluğu kutlayan bir tablo. Dostlar birbirini sırtından vurmaz."] = "DOSTLUĞU KUTLAYAN BİR TABLO. DOSTLAR BİRBİRİNİ SIRTINDAN VURMAZ.",
["Dostum, EMP bütün fabrikayı kapattı gibi... El fenerlerinizi kullanıp röntgen cihazını bulun."] = "DOSTUM, EMP BÜTÜN FABRİKAYI KAPATTI GİBİ... EL FENERLERİNİZİ KULLANIP RÖNTGEN CİHAZINI BULUN.",
["Dostum, bu benim için biraz fazla riskliydi."] = "DOSTUM, BU BENİM İÇİN BİRAZ FAZLA RİSKLİYDİ.",
["Dostum, bu dosya benden çok daha fazlasını kapsıyor. Hepinizle ilgili bilgiler var. Ama isim yok. Sanırım muhbir onları kendine saklıyor."] = "DOSTUM, BU DOSYA BENDEN ÇOK DAHA FAZLASINI KAPSIYOR. HEPİNİZLE İLGİLİ BİLGİLER VAR. AMA İSİM YOK. SANIRIM MUHBİR ONLARI KENDİNE SAKLIYOR.",
["Dostum, bu şey annenden yavaş dönüyor."] = "DOSTUM, BU ŞEY ANNENDEN YAVAŞ DÖNÜYOR.",
["Dostum, daha iyisini yapmalısın. Yanlış mermiyi atıyorsan zamanlamanın hiçbir bok önemi yok, anladın mı!"] = "DOSTUM, DAHA İYİSİNİ YAPMALISIN. YANLIŞ MERMİYİ ATIYORSAN ZAMANLAMANIN HİÇBİR BOK ÖNEMİ YOK, ANLADIN MI!",
["Dostum, devletin kurtarma parası gelsin, Detroit'i satın alacağım lan!"] = "DOSTUM, DEVLETİN KURTARMA PARASI GELSİN, DETROİT'İ SATIN ALACAĞIM LAN!",
["Dostum, gerçekten sarhoş! O adama eşlik etmek zor olacak."] = "DOSTUM, GERÇEKTEN SARHOŞ! O ADAMA EŞLİK ETMEK ZOR OLACAK.",
["Dostum, gidip kendilerini siksinler..."] = "DOSTUM, GİDİP KENDİLERİNİ SİKSİNLER...",
["Dostum, sen resmen kurşun süngerisin lan!"] = "DOSTUM, SEN RESMEN KURŞUN SÜNGERİSİN LAN!",
["Dostum, yepyeni yüz dolarlık banknotun kokusuna bayılırım. Anlıyor musun?"] = "DOSTUM, YEPYENİ YÜZ DOLARLIK BANKNOTUN KOKUSUNA BAYILIRIM. ANLIYOR MUSUN?",
["Dostum, çok güzeldi. Çok güzel. Sevgili annem gibi. (burnunu çeker)"] = "DOSTUM, ÇOK GÜZELDİ. ÇOK GÜZEL. SEVGİLİ ANNEM GİBİ. (BURNUNU ÇEKER)",
["Dostum, şehir harabeye döndü. Yollar, binalar... her şey mahvolmuş."] = "DOSTUM, ŞEHİR HARABEYE DÖNDÜ. YOLLAR, BİNALAR... HER ŞEY MAHVOLMUŞ.",
["Dostum, şu an bir bira çok iyi giderdi."] = "DOSTUM, ŞU AN BİR BİRA ÇOK İYİ GİDERDİ.",
["Dostum, şu keş yeminin kokusunu buradan aldığıma yemin edebilirim. Metamfetamin laboratuvarındayız. FBI gelmeden girip üç çuval ürün kapın. Hector ne isterse Hector alır. Şimdilik en azından."] = "DOSTUM, ŞU KEŞ YEMİNİN KOKUSUNU BURADAN ALDIĞIMA YEMİN EDEBİLİRİM. METAMFETAMİN LABORATUVARINDAYIZ. FBI GELMEDEN GİRİP ÜÇ ÇUVAL ÜRÜN KAPIN. HECTOR NE İSTERSE HECTOR ALIR. ŞİMDİLİK EN AZINDAN.",
["Dostum, şu müzik acayip güzel. Kilisede çalınmalı."] = "DOSTUM, ŞU MÜZİK ACAYİP GÜZEL. KİLİSEDE ÇALINMALI.",
["Dostum..."] = "DOSTUM...",
["Dostumuz Bile yakında parti sonrasına gelecek. Onu karşıladığınızdan emin olun."] = "DOSTUMUZ BILE YAKINDA PARTİ SONRASINA GELECEK. ONU KARŞILADIĞINIZDAN EMİN OLUN.",
["Dostumuz için anahtarı alın!"] = "DOSTUMUZ İÇİN ANAHTARI ALIN!",
["Dostumuz çıkış yolunu gösterecek! Takip edin yeter!"] = "DOSTUMUZ ÇIKIŞ YOLUNU GÖSTERECEK! TAKİP EDİN YETER!",
["Dostumuz önden gitsin, siz ilerlemeye devam edin. Dikkatlice."] = "DOSTUMUZ ÖNDEN GİTSİN, SİZ İLERLEMEYE DEVAM EDİN. DİKKATLİCE.",
["Dostumuzu geri almak için polislerle anlaşacağım. Siz bekleyin."] = "DOSTUMUZU GERİ ALMAK İÇİN POLİSLERLE ANLAŞACAĞIM. SİZ BEKLEYİN.",
["Dostumuzu takip etmeye devam edin."] = "DOSTUMUZU TAKİP ETMEYE DEVAM EDİN.",
["Dostumuzu çıkarma vakti. Nezarethane hücre bloğunun kapısını bulun, yakında olmalı."] = "DOSTUMUZU ÇIKARMA VAKTİ. NEZARETHANE HÜCRE BLOĞUNUN KAPISINI BULUN, YAKINDA OLMALI.",
["Dostumuzun bağlarını kesme vakti!"] = "DOSTUMUZUN BAĞLARINI KESME VAKTİ!",
["Dosya kontrol ediliyor"] = "DOSYA KONTROL EDİLİYOR",
["Dosyalar aranıyor"] = "DOSYALAR ARANIYOR",
["Dosyalar gerekiyor!"] = "DOSYALAR GEREKİYOR!",
["Dosyalar polis şefinin bilgisayarında olacak."] = "DOSYALAR POLİS ŞEFİNİN BİLGİSAYARINDA OLACAK.",
["Dosyalar uzatılıyor"] = "DOSYALAR UZATILIYOR",
["Dosyalara, beyaz tahtalara, duvarlara... her şeye bakın..."] = "DOSYALARA, BEYAZ TAHTALARA, DUVARLARA... HER ŞEYE BAKIN...",
["Dosyaları FBI’a yüklemeye başlamak için sunucu odasındaki bilgisayarı kullan"] = "DOSYALARI FBI’A YÜKLEMEYE BAŞLAMAK İÇİN SUNUCU ODASINDAKİ BİLGİSAYARI KULLAN",
["Dosyaları inceleyip doğru hasta dosyasını bul."] = "DOSYALARI İNCELEYİP DOĞRU HASTA DOSYASINI BUL.",
["Dosyaları yükle"] = "DOSYALARI YÜKLE",
["Dosyama girdim. Bakalım bu amcıklar ne toplamış."] = "DOSYAMA GİRDİM. BAKALIM BU AMCIKLAR NE TOPLAMIŞ.",
["Dosyamı aldım. Bakalım hakkımda neler biliyorlar."] = "DOSYAMI ALDIM. BAKALIM HAKKIMDA NELER BİLİYORLAR.",
["Doyunca çantaları buradaki havalandırmaya atmanızı istiyorum. Sonra alırız."] = "DOYUNCA ÇANTALARI BURADAKİ HAVALANDIRMAYA ATMANIZI İSTİYORUM. SONRA ALIRIZ.",
["Doğa Ana bile Vlad'i ya da Payday Gang'i durduramadı!"] = "DOĞA ANA BİLE VLAD'İ YA DA PAYDAY GANG'İ DURDURAMADI!",
["Doğayla bağını koparmamak önemli; o zaman neden bir parçasını yanında taşımayasın? Gerçekten tilki avlamıyor olabilirsin ama ganimet peşinde olduğun kesin."] = "DOĞAYLA BAĞINI KOPARMAMAK ÖNEMLİ; O ZAMAN NEDEN BİR PARÇASINI YANINDA TAŞIMAYASIN? GERÇEKTEN TİLKİ AVLAMIYOR OLABİLİRSİN AMA GANİMET PEŞİNDE OLDUĞUN KESİN.",
["Doğru adamı anlarsınız, boynunda dövme var."] = "DOĞRU ADAMI ANLARSINIZ, BOYNUNDA DÖVME VAR.",
["Doğru adresi ara"] = "DOĞRU ADRESİ ARA",
["Doğru aletlere sahip olmak işin yarısıdır."] = "DOĞRU ALETLERE SAHİP OLMAK İŞİN YARISIDIR.",
["Doğru aletlerin sahada olması, başarıyı sağlamak için büyük bir adımdır."] = "DOĞRU ALETLERİN SAHADA OLMASI, BAŞARIYI SAĞLAMAK İÇİN BÜYÜK BİR ADIMDIR.",
["Doğru anahtar orada olmalı!"] = "DOĞRU ANAHTAR ORADA OLMALI!",
["Doğru anahtarı aldığınızdan emin olun!"] = "DOĞRU ANAHTARI ALDIĞINIZDAN EMİN OLUN!",
["Doğru anahtarı bulmaya çalışın!"] = "DOĞRU ANAHTARI BULMAYA ÇALIŞIN!",
["Doğru basınca ulaşmak için Locke’un söylediği sırayla sondaj kulesinin çevresindeki vanaları çevir."] = "DOĞRU BASINCA ULAŞMAK İÇİN LOCKE’UN SÖYLEDİĞİ SIRAYLA SONDAJ KULESİNİN ÇEVRESİNDEKİ VANALARI ÇEVİR.",
["Doğru bilgisayar oralarda bir yerde olmalı."] = "DOĞRU BİLGİSAYAR ORALARDA BİR YERDE OLMALI.",
["Doğru bilgisayara dair ipuçları ofiste. Hadi, hızlanın!"] = "DOĞRU BİLGİSAYARA DAİR İPUÇLARI OFİSTE. HADİ, HIZLANIN!",
["Doğru bilgisayarı bulup sistemini kır"] = "DOĞRU BİLGİSAYARI BULUP SİSTEMİNİ KIR",
["Doğru dahili numarayla ofisteki kişiyi mutfağa çekmelisin."] = "DOĞRU DAHİLİ NUMARAYLA OFİSTEKİ KİŞİYİ MUTFAĞA ÇEKMELİSİN.",
["Doğru dedin Hox."] = "DOĞRU DEDİN HOX.",
["Doğru depolama birimini bulmalısınız!"] = "DOĞRU DEPOLAMA BİRİMİNİ BULMALISINIZ!",
["Doğru gibi görünüyor. Alın!"] = "DOĞRU GİBİ GÖRÜNÜYOR. ALIN!",
["Doğru görünüyor, şimdi parmak izini alın!"] = "DOĞRU GÖRÜNÜYOR, ŞİMDİ PARMAK İZİNİ ALIN!",
