["Durum:"] = "DURUM:",
["Durumumuz artık daha az zor. Kokain tedariki tehdit altında değil. Şimdi düşmanlarımıza karşı harekete geçeceğiz. Önümüze kim çıkarsa."] = "DURUMUMUZ ARTIK DAHA AZ ZOR. KOKAİN TEDARİKİ TEHDİT ALTINDA DEĞİL. ŞİMDİ DÜŞMANLARIMIZA KARŞI HAREKETE GEÇECEĞİZ. ÖNÜMÜZE KİM ÇIKARSA.",
["Durumumuz nasıl?"] = "DURUMUMUZ NASIL?",
["Durumunu dengelemek için bir takviyeye ihtiyacı olduğunu anlamak için doktor olmaya gerek yok. Böyle yerlerde genellikle bolca ilaç bulunur. İçinde adrenalin olan bir İlk Yardım Kiti bulmaya çalış."] = "DURUMUNU DENGELEMEK İÇİN BİR TAKVİYEYE İHTİYACI OLDUĞUNU ANLAMAK İÇİN DOKTOR OLMAYA GEREK YOK. BÖYLE YERLERDE GENELLİKLE BOLCA İLAÇ BULUNUR. İÇİNDE ADRENALİN OLAN BİR İLK YARDIM KİTİ BULMAYA ÇALIŞ.",
["Durun davetsiz misafirler!"] = "DURUN DAVETSİZ MİSAFİRLER!",
["Durun millet! Kasa Dairesi'ne tuzak döşenmiş!"] = "DURUN MİLLET! KASA DAİRESİ'NE TUZAK DÖŞENMİŞ!",
["Durun! Henüz içine koymadınız, değil mi?"] = "DURUN! HENÜZ İÇİNE KOYMADINIZ, DEĞİL Mİ?",
["Durun! Henüz koymadınız, değil mi?"] = "DURUN! HENÜZ KOYMADINIZ, DEĞİL Mİ?",
["Durun! O polisi vurmayın, yalnız! Gözünü korkutup bizim için çalıştırın!"] = "DURUN! O POLİSİ VURMAYIN, YALNIZ! GÖZÜNÜ KORKUTUP BİZİM İÇİN ÇALIŞTIRIN!",
["Durun! O zırh bir Murkywater prototipi! Bir kusuru yüzünden ısıya maruz kalınca mermilere karşı zayıflıyor. O çukurlara petrol dökün, onu aşağı çekin, sonra ateşe verin!"] = "DURUN! O ZIRH BİR MURKYWATER PROTOTİPİ! BİR KUSURU YÜZÜNDEN ISIYA MARUZ KALINCA MERMİLERE KARŞI ZAYIFLIYOR. O ÇUKURLARA PETROL DÖKÜN, ONU AŞAĞI ÇEKİN, SONRA ATEŞE VERİN!",
["Durun, DURUN! Elektrik var!"] = "DURUN, DURUN! ELEKTRİK VAR!",
["Durun, durun. Herkes arabaya binene kadar bekleyin."] = "DURUN, DURUN. HERKES ARABAYA BİNENE KADAR BEKLEYİN.",
["Durun, durun. Şunu dinleyin..."] = "DURUN, DURUN. ŞUNU DİNLEYİN...",
["Durun, işbirliği yapacağım!"] = "DURUN, İŞBİRLİĞİ YAPACAĞIM!",
["Durun, keçilerin HEPSİNİ almadınız. Göt deliğim oyuncağınız mı sizin? Keçilerin HEPSİNİ istiyorum. "] = "DURUN, KEÇİLERİN HEPSİNİ ALMADINIZ. GÖT DELİĞİM OYUNCAĞINIZ MI SİZİN? KEÇİLERİN HEPSİNİ İSTİYORUM. ",
["Durun, keçilerin bazıları eksik. Neden keçilerin bazıları eksik?!"] = "DURUN, KEÇİLERİN BAZILARI EKSİK. NEDEN KEÇİLERİN BAZILARI EKSİK?!",
["Durun, mevzi alın!"] = "DURUN, MEVZİ ALIN!",
["Durun, vurmayın! Korkutup teslim olmasını sağlayın. İşimize yarayabilir."] = "DURUN, VURMAYIN! KORKUTUP TESLİM OLMASINI SAĞLAYIN. İŞİMİZE YARAYABİLİR.",
["Durun. Cep numarası bende. Arayıp dikkatini dağıtayım. Bardağını doldurmaya hazır olun."] = "DURUN. CEP NUMARASI BENDE. ARAYIP DİKKATİNİ DAĞITAYIM. BARDAĞINI DOLDURMAYA HAZIR OLUN.",
["Durun. Ne? Gerçekten mi? Programımızda... Lanet olsun, biri şu programı berbat etmiş. Neyse, evet, burada her şey yolunda. Bu kadar dikkatli olduğunuz için teşekkürler."] = "DURUN. NE? GERÇEKTEN Mİ? PROGRAMIMIZDA... LANET OLSUN, BİRİ ŞU PROGRAMI BERBAT ETMİŞ. NEYSE, EVET, BURADA HER ŞEY YOLUNDA. BU KADAR DİKKATLİ OLDUĞUNUZ İÇİN TEŞEKKÜRLER.",
["Durun... Bir kasa dairesi daha mı?"] = "DURUN... BİR KASA DAİRESİ DAHA MI?",
["Durun... Durun... Durun... HAYIR. Lanet olsun, daha fazlasına dayanamam. Yeniden deneyin. En azından seçenekler azalıyor."] = "DURUN... DURUN... DURUN... HAYIR. LANET OLSUN, DAHA FAZLASINA DAYANAMAM. YENİDEN DENEYİN. EN AZINDAN SEÇENEKLER AZALIYOR.",
["Durun... Lobiye ya da Sosa'nın ofisine giremiyoruz. Ayrı bir sistemde olmalı."] = "DURUN... LOBİYE YA DA SOSA'NIN OFİSİNE GİREMİYORUZ. AYRI BİR SİSTEMDE OLMALI.",
["Durun... Ne... Ek güvenlik engelleri var. Devre dışı bırakmanız gerek. Bir güvenlik panosu bulup sistemin kablolarını yeniden bağlayın."] = "DURUN... NE... EK GÜVENLİK ENGELLERİ VAR. DEVRE DIŞI BIRAKMANIZ GEREK. BİR GÜVENLİK PANOSU BULUP SİSTEMİN KABLOLARINI YENİDEN BAĞLAYIN.",
["Durun... O parmaklıklarda elektrik var. Belki kesip geçebilirsiniz."] = "DURUN... O PARMAKLIKLARDA ELEKTRİK VAR. BELKİ KESİP GEÇEBİLİRSİNİZ.",
["Durup eğlenmeye vakit yok, o yönlendiricileri hemen bulun!"] = "DURUP EĞLENMEYE VAKİT YOK, O YÖNLENDİRİCİLERİ HEMEN BULUN!",
["Durup teslim olun, kaçış yolunuz kapalı."] = "DURUP TESLİM OLUN, KAÇIŞ YOLUNUZ KAPALI.",
["Duruşmayı Beklerken"] = "DURUŞMAYI BEKLERKEN",
["Duvar gibi küçücük bir şeyin önünüzü kesmesine izin vermeyeceksiniz, değil mi?"] = "DUVAR GİBİ KÜÇÜCÜK BİR ŞEYİN ÖNÜNÜZÜ KESMESİNE İZİN VERMEYECEKSİNİZ, DEĞİL Mİ?",
["Duvar gitti. Birkaç oy makinesi de güme gitti galiba. Şimdi ilerleyin!"] = "DUVAR GİTTİ. BİRKAÇ OY MAKİNESİ DE GÜME GİTTİ GALİBA. ŞİMDİ İLERLEYİN!",
["Duvar gitti. Ganimeti çöp kamyonuna bırakacaksınız. Taşımaya başlayın."] = "DUVAR GİTTİ. GANİMETİ ÇÖP KAMYONUNA BIRAKACAKSINIZ. TAŞIMAYA BAŞLAYIN.",
["Duvar gitti. Şimdi içeri girin."] = "DUVAR GİTTİ. ŞİMDİ İÇERİ GİRİN.",
["Duvar kalmadı. Girin."] = "DUVAR KALMADI. GİRİN.",
