["Dükkân açıldı! O keçiyi bulun!"] = "DÜKKÂN AÇILDI! O KEÇİYİ BULUN!",
["Dükkâna gidip bir rehine alın ki polislerle pazarlık yapıp dostumuzu geri alabilelim."] = "DÜKKÂNA GİDİP BİR REHİNE ALIN Kİ POLİSLERLE PAZARLIK YAPIP DOSTUMUZU GERİ ALABİLELİM.",
["Dükkâna girin, ne yapacağınızı biliyorsunuz! Şu mücevherleri alalım."] = "DÜKKÂNA GİRİN, NE YAPACAĞINIZI BİLİYORSUNUZ! ŞU MÜCEVHERLERİ ALALIM.",
["Dükkâna girin, sivillere dikkat edin, kameralara dikkat edin ve işi bitirin."] = "DÜKKÂNA GİRİN, SİVİLLERE DİKKAT EDİN, KAMERALARA DİKKAT EDİN VE İŞİ BİTİRİN.",
["Dükkâna girip bir rehine alın ki polislerden dostumuzu takasla geri alabilelim."] = "DÜKKÂNA GİRİP BİR REHİNE ALIN Kİ POLİSLERDEN DOSTUMUZU TAKASLA GERİ ALABİLELİM.",
["Dükkâna girip tezgâhtarı rehin alın ki polislerle takas yapabilelim."] = "DÜKKÂNA GİRİP TEZGÂHTARI REHİN ALIN Kİ POLİSLERLE TAKAS YAPABİLELİM.",
["Dükkânda polis var!"] = "DÜKKÂNDA POLİS VAR!",
["Dükkândan anlaştığımız miktarda mücevher arıyoruz... Daha fazlasını isterseniz dönüp alın."] = "DÜKKÂNDAN ANLAŞTIĞIMIZ MİKTARDA MÜCEVHER ARIYORUZ... DAHA FAZLASINI İSTERSENİZ DÖNÜP ALIN.",
["Dükkânları geri istemiyorum. Parayı ve güç gösterisini istiyorum. Gidip sert vurun! Yapınca para size gelir."] = "DÜKKÂNLARI GERİ İSTEMİYORUM. PARAYI VE GÜÇ GÖSTERİSİNİ İSTİYORUM. GİDİP SERT VURUN! YAPINCA PARA SİZE GELİR.",
["Dükkânlarımın kasalarında ve para çekmecelerinde nakit vardı; sadık insanlar benim için çok çalışırdı. Şimdi başka bir Rus için çalışıyorlar."] = "DÜKKÂNLARIMIN KASALARINDA VE PARA ÇEKMECELERİNDE NAKİT VARDI; SADIK İNSANLAR BENİM İÇİN ÇOK ÇALIŞIRDI. ŞİMDİ BAŞKA BİR RUS İÇİN ÇALIŞIYORLAR.",
["Dükkânı unutmayın. Kapıyı matkapla açın. Payıma bahse girerim, içeride keçi var."] = "DÜKKÂNI UNUTMAYIN. KAPIYI MATKAPLA AÇIN. PAYIMA BAHSE GİRERİM, İÇERİDE KEÇİ VAR.",
["Dükkânın bodrum kapısını açmak için Anahtar Kartı gerekiyor."] = "DÜKKÂNIN BODRUM KAPISINI AÇMAK İÇİN ANAHTAR KARTI GEREKİYOR.",
["Dükkânın içinde bir keçi olduğuna oldukça eminim. Kapıya bir matkap takın!"] = "DÜKKÂNIN İÇİNDE BİR KEÇİ OLDUĞUNA OLDUKÇA EMİNİM. KAPIYA BİR MATKAP TAKIN!",
["Dümdüz ileride sağda eski, iki katlı bir ev göreceksiniz. Sürpriz sürpriz, pişirme merkezi burası."] = "DÜMDÜZ İLERİDE SAĞDA ESKİ, İKİ KATLI BİR EV GÖRECEKSİNİZ. SÜRPRİZ SÜRPRİZ, PİŞİRME MERKEZİ BURASI.",
["Dümdüz ilerleyin!"] = "DÜMDÜZ İLERLEYİN!",
["Dümdüz sürmeye devam edin!"] = "DÜMDÜZ SÜRMEYE DEVAM EDİN!",
["Dün bitmeliydi millet!"] = "DÜN BİTMELİYDİ MİLLET!",
["Dün gece çaldığımız belleği kullanıp işe koyul."] = "DÜN GECE ÇALDIĞIMIZ BELLEĞİ KULLANIP İŞE KOYUL.",
["Dünya Dışı Soyguncular"] = "DÜNYA DIŞI SOYGUNCULAR",
["Dünya Geneli"] = "DÜNYA GENELİ",
["Dünya Senin"] = "DÜNYA SENİN",
["Dünya böyle bir savaş görmedi. İki taraf, sesli kitle imha silahlarıyla birbirini yok etmeye hazır. Metal, Hip hop’a karşı. Nihai hesaplaşma. Kim kazanacaktı? Zebra taytlı grup mu, pantolonlarını ters giyenler mi?"] = "DÜNYA BÖYLE BİR SAVAŞ GÖRMEDİ. İKİ TARAF, SESLİ KİTLE İMHA SİLAHLARIYLA BİRBİRİNİ YOK ETMEYE HAZIR. METAL, HİP HOP’A KARŞI. NİHAİ HESAPLAŞMA. KİM KAZANACAKTI? ZEBRA TAYTLI GRUP MU, PANTOLONLARINI TERS GİYENLER Mİ?",
["Dünya listesi alınıyor"] = "DÜNYA LİSTESİ ALINIYOR",
["Dünya çapında soyguncu olmak, silahı eline almaktan fazlasını ister. Eğitim, kondisyon ve normalin çok ötesine geçmeye adanmış bir odak gerekir. Böyle soyguncular neredeyse mutanttır; azgın savaşın içine dalıp hep muzaffer çıkarlar."] = "DÜNYA ÇAPINDA SOYGUNCU OLMAK, SİLAHI ELİNE ALMAKTAN FAZLASINI İSTER. EĞİTİM, KONDİSYON VE NORMALİN ÇOK ÖTESİNE GEÇMEYE ADANMIŞ BİR ODAK GEREKİR. BÖYLE SOYGUNCULAR NEREDEYSE MUTANTTIR; AZGIN SAVAŞIN İÇİNE DALIP HEP MUZAFFER ÇIKARLAR.",
["Dünya, chico, içindeki her şeyle birlikte."] = "DÜNYA, CHİCO, İÇİNDEKİ HER ŞEYLE BİRLİKTE.",
["Dünyada Yükselmek"] = "DÜNYADA YÜKSELMEK",
["Dünyada bir şeyin yalnızca tek örneği kaldığında o şey paha biçilmez olur. Neyi yapabildiğini, başkalarının neyi daha iyi yapabildiğini bil. İşi bitir. Kıskançlığa kapılma; o konuşan korkudur. Korku seni aşağı çeker. Sevgiden doğmaz. Birini gerçekten sevdiğinde ona güvenirsin. Paha biçilmez şeyler yüzünden kötüleşmeyecek kadar güvenirsin."] = "DÜNYADA BİR ŞEYİN YALNIZCA TEK ÖRNEĞİ KALDIĞINDA O ŞEY PAHA BİÇİLMEZ OLUR. NEYİ YAPABİLDİĞİNİ, BAŞKALARININ NEYİ DAHA İYİ YAPABİLDİĞİNİ BİL. İŞİ BİTİR. KISKANÇLIĞA KAPILMA; O KONUŞAN KORKUDUR. KORKU SENİ AŞAĞI ÇEKER. SEVGİDEN DOĞMAZ. BİRİNİ GERÇEKTEN SEVDİĞİNDE ONA GÜVENİRSİN. PAHA BİÇİLMEZ ŞEYLER YÜZÜNDEN KÖTÜLEŞMEYECEK KADAR GÜVENİRSİN.",
["Dünyada hiçbir polis bunu beklemiyordu. Ruslar köpürecek, Vlad da votkadan komaya girecek. Hadi parayı alalım."] = "DÜNYADA HİÇBİR POLİS BUNU BEKLEMİYORDU. RUSLAR KÖPÜRECEK, VLAD DA VOTKADAN KOMAYA GİRECEK. HADİ PARAYI ALALIM.",
["Dünyada o kadar çok aptal suçlu var ki akıllı olmak nispeten kolay. Çoğu insanın harekete geçmeyi seçtiği yerde biraz düşünmek yeterli."] = "DÜNYADA O KADAR ÇOK APTAL SUÇLU VAR Kİ AKILLI OLMAK NİSPETEN KOLAY. ÇOĞU İNSANIN HAREKETE GEÇMEYİ SEÇTİĞİ YERDE BİRAZ DÜŞÜNMEK YETERLİ.",
["Dünyada... bir süre... kaldıktan sonra bazı şeyleri bırakmayı öğrenirsiniz. Büyük resmi görmeyi. Bain'i buradan çıkarabilirseniz sizindir. Sonuçta ahlaken doğru seçim bu."] = "DÜNYADA... BİR SÜRE... KALDIKTAN SONRA BAZI ŞEYLERİ BIRAKMAYI ÖĞRENİRSİNİZ. BÜYÜK RESMİ GÖRMEYİ. BAIN'İ BURADAN ÇIKARABİLİRSENİZ SİZİNDİR. SONUÇTA AHLAKEN DOĞRU SEÇİM BU.",
["Dünyama, hapishaneme hoş geldin! Kendini evinde hissettireceğim. Ama yemekleri beğenmeyeceksin; başka hiçbir şeyi de!"] = "DÜNYAMA, HAPİSHANEME HOŞ GELDİN! KENDİNİ EVİNDE HİSSETTİRECEĞİM. AMA YEMEKLERİ BEĞENMEYECEKSİN; BAŞKA HİÇBİR ŞEYİ DE!",
["Dünyanın Seçkinleri"] = "DÜNYANIN SEÇKİNLERİ",
["Dünyanın en büyük turnesinin son gösterisi bu. Şimdi sıçmayın."] = "DÜNYANIN EN BÜYÜK TURNESİNİN SON GÖSTERİSİ BU. ŞİMDİ SIÇMAYIN.",
["Dünyanın en iyi forumunda biz OVERKILL ekibiyle ve diğer soyguncularla sohbet et."] = "DÜNYANIN EN İYİ FORUMUNDA BİZ OVERKILL EKİBİYLE VE DİĞER SOYGUNCULARLA SOHBET ET.",
["Dünyanın en zor işlerinden biri çok kızgın bir İngiliz’i sessiz tutmaktır. Ama bazen bu çaba gereklidir..."] = "DÜNYANIN EN ZOR İŞLERİNDEN BİRİ ÇOK KIZGIN BİR İNGİLİZ’İ SESSİZ TUTMAKTIR. AMA BAZEN BU ÇABA GEREKLİDİR...",
["Dünyanın karanlık köşelerinde soygunculardan daha eski, daha iğrenç şeyler var. Biri de Kamul. Çoktan ölmüş bir adamın burada kalmış ruhu mu, gölgeler diyarından geçmiş bir şey mi, bilmiyoruz. Tek bildiğimiz, bu yüze bakıp da anlatacak kadar yaşayanın pek az olduğu."] = "DÜNYANIN KARANLIK KÖŞELERİNDE SOYGUNCULARDAN DAHA ESKİ, DAHA İĞRENÇ ŞEYLER VAR. BİRİ DE KAMUL. ÇOKTAN ÖLMÜŞ BİR ADAMIN BURADA KALMIŞ RUHU MU, GÖLGELER DİYARINDAN GEÇMİŞ BİR ŞEY Mİ, BİLMİYORUZ. TEK BİLDİĞİMİZ, BU YÜZE BAKIP DA ANLATACAK KADAR YAŞAYANIN PEK AZ OLDUĞU.",
["Dünyanın oyunlarla yetişmiş en iyi keskin nişancısına saygı için elle yapılmış bir Deagle."] = "DÜNYANIN OYUNLARLA YETİŞMİŞ EN İYİ KESKİN NİŞANCISINA SAYGI İÇİN ELLE YAPILMIŞ BİR DEAGLE.",
["Dünyayı Değiştirmek..."] = "DÜNYAYI DEĞİŞTİRMEK...",
["Dünyayı yelkenliyle dolaşacağız. Şuradaki tekneyi görüyor musun? Bir milyon bayıldım ona, şey, bilmiyorum... Belki bu yıl denize indiririz. Bakacağız."] = "DÜNYAYI YELKENLİYLE DOLAŞACAĞIZ. ŞURADAKİ TEKNEYİ GÖRÜYOR MUSUN? BİR MİLYON BAYILDIM ONA, ŞEY, BİLMİYORUM... BELKİ BU YIL DENİZE İNDİRİRİZ. BAKACAĞIZ.",
