["Ee... Bu kötü..."] = "EE... BU KÖTÜ...",
["Ee... Harika. Evet, ben de biraz öyle yapabilirim."] = "EE... HARİKA. EVET, BEN DE BİRAZ ÖYLE YAPABİLİRİM.",
["Ee... Hoxton hiç acele etmiyor. Galiba adamı beyin sarsıntısı geçirecek kadar patakladık."] = "EE... HOXTON HİÇ ACELE ETMİYOR. GALİBA ADAMI BEYİN SARSINTISI GEÇİRECEK KADAR PATAKLADIK.",
["Ee... John... Smith. Gözünüzü açık tutun ekip. Misafir geliyor."] = "EE... JOHN... SMİTH. GÖZÜNÜZÜ AÇIK TUTUN EKİP. MİSAFİR GELİYOR.",
["Ee... Pek Harikalar Diyarı sayılmaz, değil mi?"] = "EE... PEK HARİKALAR DİYARI SAYILMAZ, DEĞİL Mİ?",
["Ee... bu, işimizi zorlaştıracak. Sıkı tutunun."] = "EE... BU, İŞİMİZİ ZORLAŞTIRACAK. SIKI TUTUNUN.",
["Ee... hı hı..."] = "EE... HI HI...",
["Ee... tamam. Ama bir dahakine alarmı çalacağım."] = "EE... TAMAM. AMA BİR DAHAKİNE ALARMI ÇALACAĞIM.",
["Ee?"] = "EE?",
["Eee, kayınbiraderim Hajrudin'i hatırlıyorsunuz, değil mi?"] = "EEE, KAYINBİRADERİM HAJRUDİN'İ HATIRLIYORSUNUZ, DEĞİL Mİ?",
["Efedrin Hapları"] = "EFEDRİN HAPLARI",
["Efedrin haplarını ekle"] = "EFEDRİN HAPLARINI EKLE",
["Efekt kalitesi"] = "EFEKT KALİTESİ",
["Efendim, bu tehlikeli. O gemiye daha fazla güvenlik lazım."] = "EFENDİM, BU TEHLİKELİ. O GEMİYE DAHA FAZLA GÜVENLİK LAZIM.",
["Efsane bir dayak attınız, üstüne bütün veri tabanını aldınız. Umarım gerekeni bulabilirim de döktüğünüz kana değer."] = "EFSANE BİR DAYAK ATTINIZ, ÜSTÜNE BÜTÜN VERİ TABANINI ALDINIZ. UMARIM GEREKENİ BULABİLİRİM DE DÖKTÜĞÜNÜZ KANA DEĞER.",
["Efsane günlerdi."] = "EFSANE GÜNLERDİ.",
["Efsane olmaya hazır mısınız?"] = "EFSANE OLMAYA HAZIR MISINIZ?",
["Efsaneler, Ay’ı Dünya’ya çarptırmaya çalışacak kadar kötücül bir varlıktan söz eder. Dört maskeli savaşçı tarafından yenilse de varlık kaçıp... bir şeye yerleşmiş. Umarız bir daha dönmez ama unutma: Bazen insan maskeyi takar, bazen de maske insanı."] = "EFSANELER, AY’I DÜNYA’YA ÇARPTIRMAYA ÇALIŞACAK KADAR KÖTÜCÜL BİR VARLIKTAN SÖZ EDER. DÖRT MASKELİ SAVAŞÇI TARAFINDAN YENİLSE DE VARLIK KAÇIP... BİR ŞEYE YERLEŞMİŞ. UMARIZ BİR DAHA DÖNMEZ AMA UNUTMA: BAZEN İNSAN MASKEYİ TAKAR, BAZEN DE MASKE İNSANI.",
["Efsanelere göre Okinawa ormanlarında alev başlı bir tilkinin ruhu yaşar. Bu tilkinin seni görmesi bir nimet sayılır ama bu maskeyi takmış bir soyguncunun seni görmesi muhtemelen öyle değildir!"] = "EFSANELERE GÖRE OKİNAWA ORMANLARINDA ALEV BAŞLI BİR TİLKİNİN RUHU YAŞAR. BU TİLKİNİN SENİ GÖRMESİ BİR NİMET SAYILIR AMA BU MASKEYİ TAKMIŞ BİR SOYGUNCUNUN SENİ GÖRMESİ MUHTEMELEN ÖYLE DEĞİLDİR!",
["Efsanevi"] = "EFSANEVİ",
["Efsanevi Bir Soyguncu"] = "EFSANEVİ BİR SOYGUNCU",
["Efsanevi Graug’un başı. Kararmış demir zırha bağlı, ateşten ve tüten karanlıktan yapılmış dev bir varlık. İnsan biçimli ama boynuzlu, yüzü de acımasız bir iblis gibi. Bedeni Cehennem’den de sıcak bir fırın hararetiyle yanıyor. En iyi şarkıların hepsini biliyor."] = "EFSANEVİ GRAUG’UN BAŞI. KARARMIŞ DEMİR ZIRHA BAĞLI, ATEŞTEN VE TÜTEN KARANLIKTAN YAPILMIŞ DEV BİR VARLIK. İNSAN BİÇİMLİ AMA BOYNUZLU, YÜZÜ DE ACIMASIZ BİR İBLİS GİBİ. BEDENİ CEHENNEM’DEN DE SICAK BİR FIRIN HARARETİYLE YANIYOR. EN İYİ ŞARKILARIN HEPSİNİ BİLİYOR.",
["Efsanevi Son Direniş"] = "EFSANEVİ SON DİRENİŞ",
["Efsanevi bir suikastçının kullandığı efsanevi bir çift hafif makineli silah."] = "EFSANEVİ BİR SUİKASTÇININ KULLANDIĞI EFSANEVİ BİR ÇİFT HAFİF MAKİNELİ SİLAH.",
["Efsanevi eşya"] = "EFSANEVİ EŞYA",
["Efsanevi soyguncu Afano \"Rocky\" Jones, Samoalı atalarının geleneklerini onurlandırıp heyecan tutkusunu doyurmak için pompalı tüfeğine en büyük başarılarından birini, Ozaki 8’i tamamlamasını simgeleyen dövmeler işledi."] = "EFSANEVİ SOYGUNCU AFANO \"ROCKY\" JONES, SAMOALI ATALARININ GELENEKLERİNİ ONURLANDIRIP HEYECAN TUTKUSUNU DOYURMAK İÇİN POMPALI TÜFEĞİNE EN BÜYÜK BAŞARILARINDAN BİRİNİ, OZAKİ 8’İ TAMAMLAMASINI SİMGELEYEN DÖVMELER İŞLEDİ.",
["Eh! Son çanta da tuvalete gitti. Üzgünüm millet, bu sefer fazladan kazanç yok."] = "EH! SON ÇANTA DA TUVALETE GİTTİ. ÜZGÜNÜM MİLLET, BU SEFER FAZLADAN KAZANÇ YOK.",
["Eh, A planı yattı. Neyse ki kalabalık hiçbirini duymadı."] = "EH, A PLANI YATTI. NEYSE Kİ KALABALIK HİÇBİRİNİ DUYMADI.",
["Eh, Chavez halledildi. Anahtarı alıp panik odasına dönün."] = "EH, CHAVEZ HALLEDİLDİ. ANAHTARI ALIP PANİK ODASINA DÖNÜN.",
["Eh, Kaptanın yardımını artık alamayız ama gemiyi hâlâ taşımamız gerek. Gemi kontrol terminaline sızın, açık kaldığından emin olun yeter."] = "EH, KAPTANIN YARDIMINI ARTIK ALAMAYIZ AMA GEMİYİ HÂLÂ TAŞIMAMIZ GEREK. GEMİ KONTROL TERMİNALİNE SIZIN, AÇIK KALDIĞINDAN EMİN OLUN YETER.",
["Eh, artık başladı. Şu kas kafalıları halledin. Malımızı alın. Çıkın."] = "EH, ARTIK BAŞLADI. ŞU KAS KAFALILARI HALLEDİN. MALIMIZI ALIN. ÇIKIN.",
["Eh, artık dönüş yok! Müthiş patlamaydı! O kamyona girip işin size düşen kısmını yapın!"] = "EH, ARTIK DÖNÜŞ YOK! MÜTHİŞ PATLAMAYDI! O KAMYONA GİRİP İŞİN SİZE DÜŞEN KISMINI YAPIN!",
["Eh, artık sessiz olmaya gerek yok. Bir şeyler döndüğünü biliyorlar!"] = "EH, ARTIK SESSİZ OLMAYA GEREK YOK. BİR ŞEYLER DÖNDÜĞÜNÜ BİLİYORLAR!",
["Eh, beni gördükten sonra yaşamasına izin vereceğimize söz vermedik ya."] = "EH, BENİ GÖRDÜKTEN SONRA YAŞAMASINA İZİN VERECEĞİMİZE SÖZ VERMEDİK YA.",
["Eh, benim ekibin işinin doğasında bu var zaten, değil mi?"] = "EH, BENİM EKİBİN İŞİNİN DOĞASINDA BU VAR ZATEN, DEĞİL Mİ?",
["Eh, bu da bitti. Beni gördü, o yüzden onu... salmam gerekti."] = "EH, BU DA BİTTİ. BENİ GÖRDÜ, O YÜZDEN ONU... SALMAM GEREKTİ.",
["Eh, bu ikinci tercih bir çözümdü. Açıkçası ben tercih etmezdim. Ama en azından o makinelerde oy kullanılamayacak. Ödeme vakti."] = "EH, BU İKİNCİ TERCİH BİR ÇÖZÜMDÜ. AÇIKÇASI BEN TERCİH ETMEZDİM. AMA EN AZINDAN O MAKİNELERDE OY KULLANILAMAYACAK. ÖDEME VAKTİ.",
["Eh, bu işte zengin olmadık ama Elephant için sorun değil. Sonraki işte daha iyisini yaparız."] = "EH, BU İŞTE ZENGİN OLMADIK AMA ELEPHANT İÇİN SORUN DEĞİL. SONRAKİ İŞTE DAHA İYİSİNİ YAPARIZ.",
["Eh, bunlar keskin nişancı."] = "EH, BUNLAR KESKİN NİŞANCI.",
["Eh, en azından bu sefer nükleer bomba değil."] = "EH, EN AZINDAN BU SEFER NÜKLEER BOMBA DEĞİL.",
["Eh, fena miktar almadınız. Benzin parasını anca çıkarır. Belki bir dahakine daha ileri gideriz."] = "EH, FENA MİKTAR ALMADINIZ. BENZİN PARASINI ANCA ÇIKARIR. BELKİ BİR DAHAKİNE DAHA İLERİ GİDERİZ.",
["Eh, füzyon yok ama en azından böylece benzin canavarı arabalarımızı daha uzun kullanabileceğiz. Ben de herkes kadar Firebird'ümü seviyorum."] = "EH, FÜZYON YOK AMA EN AZINDAN BÖYLECE BENZİN CANAVARI ARABALARIMIZI DAHA UZUN KULLANABİLECEĞİZ. BEN DE HERKES KADAR FİREBİRD'ÜMÜ SEVİYORUM.",
["Eh, gizlilik buraya kadarmış. Ama işin yarısı tamam. O parayı çıkarın yeter."] = "EH, GİZLİLİK BURAYA KADARMIŞ. AMA İŞİN YARISI TAMAM. O PARAYI ÇIKARIN YETER.",
["Eh, gördüğüm en boktan piroteknik gösteriydi neredeyse."] = "EH, GÖRDÜĞÜM EN BOKTAN PİROTEKNİK GÖSTERİYDİ NEREDEYSE.",
["Eh, hâlâ patlamadı. Son malzemeyi hazırlayabilirsiniz."] = "EH, HÂLÂ PATLAMADI. SON MALZEMEYİ HAZIRLAYABİLİRSİNİZ.",
["Eh, ideal değil ama seçimi biraz yönlendirip insanları sonucun meşruluğundan şüpheye düşürebildik. Bence The Elephant istediğini alacak. Şimdi para alma vakti."] = "EH, İDEAL DEĞİL AMA SEÇİMİ BİRAZ YÖNLENDİRİP İNSANLARI SONUCUN MEŞRULUĞUNDAN ŞÜPHEYE DÜŞÜREBİLDİK. BENCE THE ELEPHANT İSTEDİĞİNİ ALACAK. ŞİMDİ PARA ALMA VAKTİ.",
["Eh, işe yaramadı. Daha büyük bir şey lazım. Şu avize olabilir... Kablolardan birini termitle eritin!"] = "EH, İŞE YARAMADI. DAHA BÜYÜK BİR ŞEY LAZIM. ŞU AVİZE OLABİLİR... KABLOLARDAN BİRİNİ TERMİTLE ERİTİN!",
["Eh, kaçabilirsiniz tabii, sorun değil. Ya da... Bir fikir var. Kalıp daha fazla elfe zorbalık edebilir, daha güzel kar yapabilirsiniz!"] = "EH, KAÇABİLİRSİNİZ TABİİ, SORUN DEĞİL. YA DA... BİR FİKİR VAR. KALIP DAHA FAZLA ELFE ZORBALIK EDEBİLİR, DAHA GÜZEL KAR YAPABİLİRSİNİZ!",
["Eh, kokainin birazını kaybettiniz ama işi bitirdiniz. Aferin! Paramızı yine alacağız. Bu arada enseye biraz buz koyun."] = "EH, KOKAİNİN BİRAZINI KAYBETTİNİZ AMA İŞİ BİTİRDİNİZ. AFERİN! PARAMIZI YİNE ALACAĞIZ. BU ARADA ENSEYE BİRAZ BUZ KOYUN.",
["Eh, muhtemelen bir dünya para eder."] = "EH, MUHTEMELEN BİR DÜNYA PARA EDER.",
["Eh, ne zaman arayacağını merak ediyordum."] = "EH, NE ZAMAN ARAYACAĞINI MERAK EDİYORDUM.",
["Eh, oldu işte. Artık sessiz kalmanın anlamı yok. Silahları çıkarın, olur mu?"] = "EH, OLDU İŞTE. ARTIK SESSİZ KALMANIN ANLAMI YOK. SİLAHLARI ÇIKARIN, OLUR MU?",
["Eh, oldu işte. Burada olduğumuzu biliyorlar. Ağır silahları çıkarıp bizim Ukraynalıyı eve getirin!"] = "EH, OLDU İŞTE. BURADA OLDUĞUMUZU BİLİYORLAR. AĞIR SİLAHLARI ÇIKARIP BİZİM UKRAYNALIYI EVE GETİRİN!",
["Eh, ona kolay para oldu. Aklınıza takmayın. Devam edin millet."] = "EH, ONA KOLAY PARA OLDU. AKLINIZA TAKMAYIN. DEVAM EDİN MİLLET.",
["Eh, sadece 14 tane kaldı."] = "EH, SADECE 14 TANE KALDI.",
["Eh, siktir et. Onu fark edilmeden geçemeyeceksiniz galiba. İndirin."] = "EH, SİKTİR ET. ONU FARK EDİLMEDEN GEÇEMEYECEKSİNİZ GALİBA. İNDİRİN.",
["Eh, sizin yerinize söyleyeyim: Buraya sadece beni kurtarmaya gelmediniz, değil mi? Hayır, özel yapım motor için geldiniz. Haklı mıyım, haklı mıyım? Yardım ederim. Size o kadar borcum var ama gereken parçaları getirmelisiniz."] = "EH, SİZİN YERİNİZE SÖYLEYEYİM: BURAYA SADECE BENİ KURTARMAYA GELMEDİNİZ, DEĞİL Mİ? HAYIR, ÖZEL YAPIM MOTOR İÇİN GELDİNİZ. HAKLI MIYIM, HAKLI MIYIM? YARDIM EDERİM. SİZE O KADAR BORCUM VAR AMA GEREKEN PARÇALARI GETİRMELİSİNİZ.",
["Eh, suç tarihinin çuvallamaları arasında bu üst sıralarda. Polislerin güldüğünü buradan duyuyorum. Bir dahaki sefere bol şans."] = "EH, SUÇ TARİHİNİN ÇUVALLAMALARI ARASINDA BU ÜST SIRALARDA. POLİSLERİN GÜLDÜĞÜNÜ BURADAN DUYUYORUM. BİR DAHAKİ SEFERE BOL ŞANS.",
["Eh, tamam o zaman..."] = "EH, TAMAM O ZAMAN...",
["Eh, ön kapı kapalı. Şaşırtıcı değil. Başka bir giriş arayın."] = "EH, ÖN KAPI KAPALI. ŞAŞIRTICI DEĞİL. BAŞKA BİR GİRİŞ ARAYIN.",
["Eh, ıskaladım... Millet, C4 balkona düştü. Kusura bakmayın."] = "EH, ISKALADIM... MİLLET, C4 BALKONA DÜŞTÜ. KUSURA BAKMAYIN.",
["Eh, şimdi iş bozuldu."] = "EH, ŞİMDİ İŞ BOZULDU.",
["Eh... Daha kötüsünü de yaptık sanırım."] = "EH... DAHA KÖTÜSÜNÜ DE YAPTIK SANIRIM.",
["Eh... Yarınki GenSec hissedarlar toplantısında kötü haberler olacak."] = "EH... YARINKİ GENSEC HİSSEDARLAR TOPLANTISINDA KÖTÜ HABERLER OLACAK.",
["Ejderha Avcısı"] = "EJDERHA AVCISI",
["Ejderha Heykeli"] = "EJDERHA HEYKELİ",
["Ejderha Hırsızı"] = "EJDERHA HIRSIZI",
["Ejderha bağırıyorsa kaplan kükrer mi? Genellikle soygunda yüksek sesle kendini belli etmek başarıya zarar verir. Ama bazen sırf havalı olduğu için akışına bırakmalısın. O yüzden hadi... Kendini şımart."] = "EJDERHA BAĞIRIYORSA KAPLAN KÜKRER Mİ? GENELLİKLE SOYGUNDA YÜKSEK SESLE KENDİNİ BELLİ ETMEK BAŞARIYA ZARAR VERİR. AMA BAZEN SIRF HAVALI OLDUĞU İÇİN AKIŞINA BIRAKMALISIN. O YÜZDEN HADİ... KENDİNİ ŞIMART.",
["Ejderha bir sandıkta ama sandıklar tuzaklı olabilir, doğru olanı bulalım. Gereksiz şeyleri açıp gürültü çıkarmaya gerek yok. Bilgisayar sistemlerinde muhtemelen bir manifesto tutuyorlardır."] = "EJDERHA BİR SANDIKTA AMA SANDIKLAR TUZAKLI OLABİLİR, DOĞRU OLANI BULALIM. GEREKSİZ ŞEYLERİ AÇIP GÜRÜLTÜ ÇIKARMAYA GEREK YOK. BİLGİSAYAR SİSTEMLERİNDE MUHTEMELEN BİR MANİFESTO TUTUYORLARDIR.",
["Ejderha heykeli alınıyor"] = "EJDERHA HEYKELİ ALINIYOR",
["Ejderha heykeline iyi bakmadın. Sonra bak ne oldu!"] = "EJDERHA HEYKELİNE İYİ BAKMADIN. SONRA BAK NE OLDU!",
["Ejderha heykelini güvenceye al"] = "EJDERHA HEYKELİNİ GÜVENCEYE AL",
["Ejderha heykelini halletmediniz, bakın ne oldu!"] = "EJDERHA HEYKELİNİ HALLETMEDİNİZ, BAKIN NE OLDU!",
["Ejderha neden hiç kazanmaz?"] = "EJDERHA NEDEN HİÇ KAZANMAZ?",
["Ejderhalar güler mi? Gerçekten mi? Bazıları terbiyeli olsa da genelde huysuz piçlerdir. Bir de bunu takıp kocaman bir el topuyla sana ateş eden bir soyguncunun karşısında olduğunu düşün."] = "EJDERHALAR GÜLER Mİ? GERÇEKTEN Mİ? BAZILARI TERBİYELİ OLSA DA GENELDE HUYSUZ PİÇLERDİR. BİR DE BUNU TAKIP KOCAMAN BİR EL TOPUYLA SANA ATEŞ EDEN BİR SOYGUNCUNUN KARŞISINDA OLDUĞUNU DÜŞÜN.",
["Ejderhanın Peşinde"] = "EJDERHANIN PEŞİNDE",
["Ejderhayı Uyandır"] = "EJDERHAYI UYANDIR",
["Ek Anahtar Kart"] = "EK ANAHTAR KART",
["Ek Batarya"] = "EK BATARYA",
["Ek Beast matkap uçları"] = "EK BEAST MATKAP UÇLARI",
["Ek Ceset Torbaları"] = "EK CESET TORBALARI",
["Ek Ganimet Teslim Noktası"] = "EK GANİMET TESLİM NOKTASI",
["Ek Ganimet Çantaları"] = "EK GANİMET ÇANTALARI",
["Ek Giriş Noktası"] = "EK GİRİŞ NOKTASI",
["Ek Helikopter Yakıtı"] = "EK HELİKOPTER YAKITI",
["Ek Kameralar"] = "EK KAMERALAR",
["Ek Kesici"] = "EK KESİCİ",
["Ek Kurşun"] = "EK KURŞUN",
["Ek Motor Gücü"] = "EK MOTOR GÜCÜ",
["Ek Para"] = "EK PARA",
["Ek Plastik Kelepçeler sayesinde soyguna daha fazla Plastik Kelepçeyle başlarsın. Sayıları yükseltme seviyesine bağlıdır."] = "EK PLASTİK KELEPÇELER SAYESİNDE SOYGUNA DAHA FAZLA PLASTİK KELEPÇEYLE BAŞLARSIN. SAYILARI YÜKSELTME SEVİYESİNE BAĞLIDIR.",
["Ek Silah Parçaları"] = "EK SİLAH PARÇALARI",
["Ek Termal Matkap"] = "EK TERMAL MATKAP",
["Ek Zırh"] = "EK ZIRH",
["Ek başlangıç mühimmatı, sahibinin daha fazla mühimmat taşımasını sağlar. Miktarı yükseltme seviyesine bağlıdır."] = "EK BAŞLANGIÇ MÜHİMMATI, SAHİBİNİN DAHA FAZLA MÜHİMMAT TAŞIMASINI SAĞLAR. MİKTARI YÜKSELTME SEVİYESİNE BAĞLIDIR.",
["Ek bir deri katmanı her zaman iyi fikirdir. Bir de bu kadar iyi görünüyorsa en budala adam bile sana bulaşmadan önce iki kere düşünür."] = "EK BİR DERİ KATMANI HER ZAMAN İYİ FİKİRDİR. BİR DE BU KADAR İYİ GÖRÜNÜYORSA EN BUDALA ADAM BİLE SANA BULAŞMADAN ÖNCE İKİ KERE DÜŞÜNÜR.",
["Ek bir ganimet teslim noktası ayarla"] = "EK BİR GANİMET TESLİM NOKTASI AYARLA",
["Ek ganimet arıyorsanız gerçekten yanlış yerdesiniz. Çıkın oradan."] = "EK GANİMET ARIYORSANIZ GERÇEKTEN YANLIŞ YERDESİNİZ. ÇIKIN ORADAN.",
["Ek ganimet güzel ama onun parasını almalıyız. Paranın bulunduğu kasayı bul. Bir yerde olmalı!"] = "EK GANİMET GÜZEL AMA ONUN PARASINI ALMALIYIZ. PARANIN BULUNDUĞU KASAYI BUL. BİR YERDE OLMALI!",
["Ek ganimet için diğer vagonlara bakın. Bir de C4. Onu da arayın."] = "EK GANİMET İÇİN DİĞER VAGONLARA BAKIN. BİR DE C4. ONU DA ARAYIN.",
["Ek ganimeti güvenceye al veya kaç"] = "EK GANİMETİ GÜVENCEYE AL VEYA KAÇ",
["Ek ganimeti güvenceye almak ve apartman binasından kaçmak için helikopteri kullan."] = "EK GANİMETİ GÜVENCEYE ALMAK VE APARTMAN BİNASINDAN KAÇMAK İÇİN HELİKOPTERİ KULLAN.",
