["Ekip Takviyesi:"] = "EKİP TAKVİYESİ:",
["Ekip Yapay Zekâsı veya başka oyuncular olmadan tek başına oynuyorsan Cloaker birimleri sana hücum etmez."] = "EKİP YAPAY ZEKÂSI VEYA BAŞKA OYUNCULAR OLMADAN TEK BAŞINA OYNUYORSAN CLOAKER BİRİMLERİ SANA HÜCUM ETMEZ.",
["Ekip Yönetimi"] = "EKİP YÖNETİMİ",
["Ekip arkadaşların gözaltına alındıysa onları takasla geri getirmek için bir rehineye veya teslim alınmış bir polise ihtiyacın var."] = "EKİP ARKADAŞLARIN GÖZALTINA ALINDIYSA ONLARI TAKASLA GERİ GETİRMEK İÇİN BİR REHİNEYE VEYA TESLİM ALINMIŞ BİR POLİSE İHTİYACIN VAR.",
["Ekip arkadaşların hakkında bilgi almak için oyun menüsündeki FBI dosyalarını okuyabilirsin."] = "EKİP ARKADAŞLARIN HAKKINDA BİLGİ ALMAK İÇİN OYUN MENÜSÜNDEKİ FBI DOSYALARINI OKUYABİLİRSİN.",
