["Ekip arkadaşına yardım et"] = "EKİP ARKADAŞINA YARDIM ET",
["Ekip arkadaşını gözaltından kurtarmak için bu rehineyi serbest bırak!"] = "EKİP ARKADAŞINI GÖZALTINDAN KURTARMAK İÇİN BU REHİNEYİ SERBEST BIRAK!",
["Ekip arkadaşını polisten takasla geri almak için bir rehine al."] = "EKİP ARKADAŞINI POLİSTEN TAKASLA GERİ ALMAK İÇİN BİR REHİNE AL.",
