["Ekip lobisi"] = "EKİP LOBİSİ",
["Ekip Çalışması"] = "EKİP ÇALIŞMASI",
["Ekip! Dikkatinizi dağıtmayın. Nakit için geldik, orada da sizi bekliyor."] = "EKİP! DİKKATİNİZİ DAĞITMAYIN. NAKİT İÇİN GELDİK, ORADA DA SİZİ BEKLİYOR.",
["Ekip! Çıkın oradan! Ne halt ediyorsunuz?"] = "EKİP! ÇIKIN ORADAN! NE HALT EDİYORSUNUZ?",
["Ekip, C4 minibüste. Alıp yerleştirin."] = "EKİP, C4 MİNİBÜSTE. ALIP YERLEŞTİRİN.",
["Ekip, GenSec kamyonu. Hey, anahtar kartı taşıyor olabilir. Ne yapacağınızı biliyorsunuz. Üstlerine gidin."] = "EKİP, GENSEC KAMYONU. HEY, ANAHTAR KARTI TAŞIYOR OLABİLİR. NE YAPACAĞINIZI BİLİYORSUNUZ. ÜSTLERİNE GİDİN.",
["Ekip, Mendoza'nın DC operasyonlarını burada ve şimdi bitiriyoruz. O otobüsü sert vurup paralarını alın. Hector sadece bu palyaçoların bitmesini istiyor, para bizim. İnişe 3, 2, 1, gidin!"] = "EKİP, MENDOZA'NIN DC OPERASYONLARINI BURADA VE ŞİMDİ BİTİRİYORUZ. O OTOBÜSÜ SERT VURUP PARALARINI ALIN. HECTOR SADECE BU PALYAÇOLARIN BİTMESİNİ İSTİYOR, PARA BİZİM. İNİŞE 3, 2, 1, GİDİN!",
["Ekip, anahtar kartı olmadan o kapıyı geçemeyiz. Arayın."] = "EKİP, ANAHTAR KARTI OLMADAN O KAPIYI GEÇEMEYİZ. ARAYIN.",
["Ekip, baş bilim insanını bulmalısınız."] = "EKİP, BAŞ BİLİM İNSANINI BULMALISINIZ.",
["Ekip, benzin bulun ve lastikleri yakın. O helikoptere uğraşacağı güzel, yoğun bir sis perdesi verin!"] = "EKİP, BENZİN BULUN VE LASTİKLERİ YAKIN. O HELİKOPTERE UĞRAŞACAĞI GÜZEL, YOĞUN BİR SİS PERDESİ VERİN!",
["Ekip, bu haber daha yeni geldi. Bizi bekleyen bir altın deposu var. "] = "EKİP, BU HABER DAHA YENİ GELDİ. BİZİ BEKLEYEN BİR ALTIN DEPOSU VAR. ",
["Ekip, dikilip durmayın. Kaçış noktasına gidin. Mavi konteynerleri takip edin!"] = "EKİP, DİKİLİP DURMAYIN. KAÇIŞ NOKTASINA GİDİN. MAVİ KONTEYNERLERİ TAKİP EDİN!",
["Ekip, duydunuz mu? Pilot geliyor. Keçileri koruyun."] = "EKİP, DUYDUNUZ MU? PİLOT GELİYOR. KEÇİLERİ KORUYUN.",
["Ekip, elektriğin bilgisayarlar için ne kadar önemli olduğunu daha nasıl anlatayım!"] = "EKİP, ELEKTRİĞİN BİLGİSAYARLAR İÇİN NE KADAR ÖNEMLİ OLDUĞUNU DAHA NASIL ANLATAYIM!",
["Ekip, eve girin. Hadi kımıldayın!"] = "EKİP, EVE GİRİN. HADİ KIMILDAYIN!",
["Ekip, görüyor musunuz? İskelede başka bir keçi! Ama vay, dikkat edin! O merdivende elektrik var gibi!"] = "EKİP, GÖRÜYOR MUSUNUZ? İSKELEDE BAŞKA BİR KEÇİ! AMA VAY, DİKKAT EDİN! O MERDİVENDE ELEKTRİK VAR GİBİ!",
["Ekip, hâlâ o radarı patlatmanız gerekiyor."] = "EKİP, HÂLÂ O RADARI PATLATMANIZ GEREKİYOR.",
["Ekip, hâlâ o çelik kapıyı geçmenin bir yolu lazım. Kullanabileceğimiz bir şey bulmalısınız."] = "EKİP, HÂLÂ O ÇELİK KAPIYI GEÇMENİN BİR YOLU LAZIM. KULLANABİLECEĞİMİZ BİR ŞEY BULMALISINIZ.",
["Ekip, inşaat alanına girin! Çabuk!"] = "EKİP, İNŞAAT ALANINA GİRİN! ÇABUK!",
["Ekip, kapıyı delmeye başlayın. Çabuk olun!"] = "EKİP, KAPIYI DELMEYE BAŞLAYIN. ÇABUK OLUN!",
["Ekip, kasa dairesinin sistemini kıracak bir şey olmadan açamayız. Aramaya devam edin!"] = "EKİP, KASA DAİRESİNİN SİSTEMİNİ KIRACAK BİR ŞEY OLMADAN AÇAMAYIZ. ARAMAYA DEVAM EDİN!",
["Ekip, kaçmanız lazım. Mavi konteynerler kaçış yolunu gösterecek."] = "EKİP, KAÇMANIZ LAZIM. MAVİ KONTEYNERLER KAÇIŞ YOLUNU GÖSTERECEK.",
["Ekip, kendinizi kuşatılmış sayın. Etrafınızı sardılar, keskin nişancılar kuruyorlar. Yerinizde olsam içeride kalırdım!"] = "EKİP, KENDİNİZİ KUŞATILMIŞ SAYIN. ETRAFINIZI SARDILAR, KESKİN NİŞANCILAR KURUYORLAR. YERİNİZDE OLSAM İÇERİDE KALIRDIM!",
["Ekip, keçilerden birinin yukarıdaki dairede olduğunu unutmayın."] = "EKİP, KEÇİLERDEN BİRİNİN YUKARIDAKİ DAİREDE OLDUĞUNU UNUTMAYIN.",
["Ekip, keçileri aldınız. Şimdi gaza basın!"] = "EKİP, KEÇİLERİ ALDINIZ. ŞİMDİ GAZA BASIN!",
["Ekip, lastikleri yakın. O helikoptere uğraşacak kalın bir duman perdesi verin!"] = "EKİP, LASTİKLERİ YAKIN. O HELİKOPTERE UĞRAŞACAK KALIN BİR DUMAN PERDESİ VERİN!",
["Ekip, metal dedektörlerini halletmelisiniz. Çok elektrik tüketiyorlar. Sigorta kutularını bulup kapatın."] = "EKİP, METAL DEDEKTÖRLERİNİ HALLETMELİSİNİZ. ÇOK ELEKTRİK TÜKETİYORLAR. SİGORTA KUTULARINI BULUP KAPATIN.",
["Ekip, ne bekliyorsunuz? Binaya girin."] = "EKİP, NE BEKLİYORSUNUZ? BİNAYA GİRİN.",
["Ekip, ne oluyor? Evrak çantası olmadan gitmiyoruz."] = "EKİP, NE OLUYOR? EVRAK ÇANTASI OLMADAN GİTMİYORUZ.",
["Ekip, nehrin karşısında bir inşaat alanı var! Park etmiş bir kamyon var. Bence en iyi çıkış yolumuz o. Şimdi size C4 gönderiyorum. Kasaları koruyun!"] = "EKİP, NEHRİN KARŞISINDA BİR İNŞAAT ALANI VAR! PARK ETMİŞ BİR KAMYON VAR. BENCE EN İYİ ÇIKIŞ YOLUMUZ O. ŞİMDİ SİZE C4 GÖNDERİYORUM. KASALARI KORUYUN!",
["Ekip, o Kasa Dairesini bulun. Bir sevkiyat konteynerinde olacak. Muhtemelen şu Murkywater konteynerlerinde."] = "EKİP, O KASA DAİRESİNİ BULUN. BİR SEVKİYAT KONTEYNERİNDE OLACAK. MUHTEMELEN ŞU MURKYWATER KONTEYNERLERİNDE.",
["Ekip, o ateş tuzağı kaçış noktamızın yanında olmalı. Vinç kumandalarını kullanın."] = "EKİP, O ATEŞ TUZAĞI KAÇIŞ NOKTAMIZIN YANINDA OLMALI. VİNÇ KUMANDALARINI KULLANIN.",
["Ekip, o kalıpları görüyor musunuz? Açgözlülük yapmak istemem... Aslında evet, isterim. Biraz daha kalıp şu baskı makinesini denesek ya?"] = "EKİP, O KALIPLARI GÖRÜYOR MUSUNUZ? AÇGÖZLÜLÜK YAPMAK İSTEMEM... ASLINDA EVET, İSTERİM. BİRAZ DAHA KALIP ŞU BASKI MAKİNESİNİ DENESEK YA?",
["Ekip, o kesiciyi Kasa Dairesinin zeminine koyun. Şunu kesip açalım."] = "EKİP, O KESİCİYİ KASA DAİRESİNİN ZEMİNİNE KOYUN. ŞUNU KESİP AÇALIM.",
["Ekip, o kesiciyle ilgilenmeniz gerek."] = "EKİP, O KESİCİYLE İLGİLENMENİZ GEREK.",
["Ekip, o kinci piç Commissar sırf inat olsun diye bir servet değerinde kokaini döküyor! Yukarı çıkıp kurtarın. Ne kadar hızlı olursanız o kadarını kurtarırsınız!"] = "EKİP, O KİNCİ PİÇ COMMİSSAR SIRF İNAT OLSUN DİYE BİR SERVET DEĞERİNDE KOKAİNİ DÖKÜYOR! YUKARI ÇIKIP KURTARIN. NE KADAR HIZLI OLURSANIZ O KADARINI KURTARIRSINIZ!",
["Ekip, o matkap çalışmadan hiçbir yere gidemeyiz."] = "EKİP, O MATKAP ÇALIŞMADAN HİÇBİR YERE GİDEMEYİZ.",
["Ekip, o tareti bulmanız gerek."] = "EKİP, O TARETİ BULMANIZ GEREK.",
["Ekip, o uçaksavarları bir an önce halletmelisiniz. Bir yol bulun!"] = "EKİP, O UÇAKSAVARLARI BİR AN ÖNCE HALLETMELİSİNİZ. BİR YOL BULUN!",
["Ekip, onu indirin. Belki biraz güç yeter."] = "EKİP, ONU İNDİRİN. BELKİ BİRAZ GÜÇ YETER.",
["Ekip, onu tarayıcıya götürün. Kullanmasını sağlayın!"] = "EKİP, ONU TARAYICIYA GÖTÜRÜN. KULLANMASINI SAĞLAYIN!",
["Ekip, paraşütlerle acele edin. Rotadan çıkmayın."] = "EKİP, PARAŞÜTLERLE ACELE EDİN. ROTADAN ÇIKMAYIN.",
["Ekip, pek de dostça olmayan küçük bir iknanın ardından Kento’ya dair ipucu aldık. Kazuo adlı bir adamda bize lazım bilgi varmış ama küçük bir pürüz var: D.C. Central’da parmaklıklar arkasında. Neyse ki nakil ayarladım. Tek yapmamız gereken nakil sırasında onu almak. Bu iş çok gürültülü olacak; sonrasında D.D.O.T.’nin bizi pek seveceğini sanmıyorum. Çünkü çukurdan fazlasını tamir edecekler: bir köprüyü yıkıyoruz!"] = "EKİP, PEK DE DOSTÇA OLMAYAN KÜÇÜK BİR İKNANIN ARDINDAN KENTO’YA DAİR İPUCU ALDIK. KAZUO ADLI BİR ADAMDA BİZE LAZIM BİLGİ VARMIŞ AMA KÜÇÜK BİR PÜRÜZ VAR: D.C. CENTRAL’DA PARMAKLIKLAR ARKASINDA. NEYSE Kİ NAKİL AYARLADIM. TEK YAPMAMIZ GEREKEN NAKİL SIRASINDA ONU ALMAK. BU İŞ ÇOK GÜRÜLTÜLÜ OLACAK; SONRASINDA D.D.O.T.’NİN BİZİ PEK SEVECEĞİNİ SANMIYORUM. ÇÜNKÜ ÇUKURDAN FAZLASINI TAMİR EDECEKLER: BİR KÖPRÜYÜ YIKIYORUZ!",
["Ekip, pilot sizi göremiyor. O işaret fişeğini yakmalısınız."] = "EKİP, PİLOT SİZİ GÖREMİYOR. O İŞARET FİŞEĞİNİ YAKMALISINIZ.",
["Ekip, polis teşkilatına pek saygı göstermiyor olabilir ama arkalarında bıraktıkları yanan enkazları temizleyen kadınlara ve erkeklere büyük saygı duyuyor. Bu maske onların çabalarına bir saygı duruşu."] = "EKİP, POLİS TEŞKİLATINA PEK SAYGI GÖSTERMİYOR OLABİLİR AMA ARKALARINDA BIRAKTIKLARI YANAN ENKAZLARI TEMİZLEYEN KADINLARA VE ERKEKLERE BÜYÜK SAYGI DUYUYOR. BU MASKE ONLARIN ÇABALARINA BİR SAYGI DURUŞU.",
["Ekip, polis üç sokaklık çevreyi kuşattı. Zor yol tek yol, o yüzden yürüyorsunuz. Kamyondan ayrılmayın, kamyon da sizden ayrılmaz."] = "EKİP, POLİS ÜÇ SOKAKLIK ÇEVREYİ KUŞATTI. ZOR YOL TEK YOL, O YÜZDEN YÜRÜYORSUNUZ. KAMYONDAN AYRILMAYIN, KAMYON DA SİZDEN AYRILMAZ.",
["Ekip, polisler şehri tecride aldı. Tek seçenek savaşarak geçmek, o yüzden sizi yerde istiyoruz. Yani kamyon sizinle kalacak."] = "EKİP, POLİSLER ŞEHRİ TECRİDE ALDI. TEK SEÇENEK SAVAŞARAK GEÇMEK, O YÜZDEN SİZİ YERDE İSTİYORUZ. YANİ KAMYON SİZİNLE KALACAK.",
["Ekip, sıvışma vakti. Arabaya binin!"] = "EKİP, SIVIŞMA VAKTİ. ARABAYA BİNİN!",
["Ekip, sığınağa gidin! Çabuk!"] = "EKİP, SIĞINAĞA GİDİN! ÇABUK!",
["Ekip, telsizi kullanın. Gemimizle konuşayım."] = "EKİP, TELSİZİ KULLANIN. GEMİMİZLE KONUŞAYIM.",
["Ekip, tuzağı ateşleyin!"] = "EKİP, TUZAĞI ATEŞLEYİN!",
["Ekip, unutmayın. Locke o işaret fişeğini yakmanızı istiyor."] = "EKİP, UNUTMAYIN. LOCKE O İŞARET FİŞEĞİNİ YAKMANIZI İSTİYOR.",
["Ekip, unutmayın: Altını 61 numaralı konteynere taşıyın."] = "EKİP, UNUTMAYIN: ALTINI 61 NUMARALI KONTEYNERE TAŞIYIN.",
["Ekip, unutmayın: Locke gelmeden önce bir işaret fişeği yakmalısınız."] = "EKİP, UNUTMAYIN: LOCKE GELMEDEN ÖNCE BİR İŞARET FİŞEĞİ YAKMALISINIZ.",
["Ekip, yangınları söndürün. Kargaşada kaçmasını göze almak istemeyiz."] = "EKİP, YANGINLARI SÖNDÜRÜN. KARGAŞADA KAÇMASINI GÖZE ALMAK İSTEMEYİZ.",
["Ekip, çantayı kapıp met laboratuvarının yanına bırakın."] = "EKİP, ÇANTAYI KAPIP MET LABORATUVARININ YANINA BIRAKIN.",
["Ekip, çıkmak için en iyi yolunuz karşıdaki şantiye gibi görünüyor. Bir kamyonları var. Duvarı yıkmanız için şimdi biraz C4 yolluyorum."] = "EKİP, ÇIKMAK İÇİN EN İYİ YOLUNUZ KARŞIDAKİ ŞANTİYE GİBİ GÖRÜNÜYOR. BİR KAMYONLARI VAR. DUVARI YIKMANIZ İÇİN ŞİMDİ BİRAZ C4 YOLLUYORUM.",
["Ekip, şarj olurken EMP'yi korumalısınız! Savaşmaya hazırlanın!"] = "EKİP, ŞARJ OLURKEN EMP'Yİ KORUMALISINIZ! SAVAŞMAYA HAZIRLANIN!",
["Ekip, şuradaki bilgisayar istasyonu işe yarayabilir. Bana dizüstü bilgisayar falan bulmaya çalışın."] = "EKİP, ŞURADAKİ BİLGİSAYAR İSTASYONU İŞE YARAYABİLİR. BANA DİZÜSTÜ BİLGİSAYAR FALAN BULMAYA ÇALIŞIN.",
["Ekip. GenSec zaman kilidi kodlarını istiyor. Onları olabildiğince oyalayacağım. Kodları görebiliyor musunuz?"] = "EKİP. GENSEC ZAMAN KİLİDİ KODLARINI İSTİYOR. ONLARI OLABİLDİĞİNCE OYALAYACAĞIM. KODLARI GÖREBİLİYOR MUSUNUZ?",
