["Evet, şeker falan değil."] = "EVET, ŞEKER FALAN DEĞİL.",
["Evet, şey. Düzenli zaman kilidi kontrolü için hazır bulunmazsa kıçının tehlikede olduğunu söyleyin."] = "EVET, ŞEY. DÜZENLİ ZAMAN KİLİDİ KONTROLÜ İÇİN HAZIR BULUNMAZSA KIÇININ TEHLİKEDE OLDUĞUNU SÖYLEYİN.",
["Evet, şey... Buradaki ekran bozuldu. Çok gürültü yaptı. Yaşlı bir kadını korkuttu ama temizlikçi onunla ilgilendi."] = "EVET, ŞEY... BURADAKİ EKRAN BOZULDU. ÇOK GÜRÜLTÜ YAPTI. YAŞLI BİR KADINI KORKUTTU AMA TEMİZLİKÇİ ONUNLA İLGİLENDİ.",
["Evet, şimdi oraya gidiyorum!"] = "EVET, ŞİMDİ ORAYA GİDİYORUM!",
["Evet, şimdi çatıda keskin nişancılar görüyorum... Dikkat edin."] = "EVET, ŞİMDİ ÇATIDA KESKİN NİŞANCILAR GÖRÜYORUM... DİKKAT EDİN.",
["Evet, şimdi çatıda keskin nişancılar görüyorum... dikkat edin!"] = "EVET, ŞİMDİ ÇATIDA KESKİN NİŞANCILAR GÖRÜYORUM... DİKKAT EDİN!",
["Evet. Ama hayır. Kesinlikle hayır."] = "EVET. AMA HAYIR. KESİNLİKLE HAYIR.",
["Evet. Birinin palyaçolardan bahsettiğini duydum. Ne delilik."] = "EVET. BİRİNİN PALYAÇOLARDAN BAHSETTİĞİNİ DUYDUM. NE DELİLİK.",
["Evet. Bunları sana hangi salak öğretti?"] = "EVET. BUNLARI SANA HANGİ SALAK ÖĞRETTİ?",
["Evet. Demek ki yapacak çok işimiz var..."] = "EVET. DEMEK Kİ YAPACAK ÇOK İŞİMİZ VAR...",
["Evet. Doğru duydunuz. Vlad ciddi. Alışveriş merkezine girip kırabildiğimiz kadar çok şeyi kıracağız."] = "EVET. DOĞRU DUYDUNUZ. VLAD CİDDİ. ALIŞVERİŞ MERKEZİNE GİRİP KIRABİLDİĞİMİZ KADAR ÇOK ŞEYİ KIRACAĞIZ.",
["Evet. Doğru duydunuz. Vlad ciddi. Alışveriş merkezine girip kırabildiğimiz kadar çok şeyi kıracağız. Yeterince zarar verirsek müşterisi haraç konusundaki tavrını yeniden düşünür. Kirli iş ama siz kirlenmeyi seversiniz, değil mi?"] = "EVET. DOĞRU DUYDUNUZ. VLAD CİDDİ. ALIŞVERİŞ MERKEZİNE GİRİP KIRABİLDİĞİMİZ KADAR ÇOK ŞEYİ KIRACAĞIZ. YETERİNCE ZARAR VERİRSEK MÜŞTERİSİ HARAÇ KONUSUNDAKİ TAVRINI YENİDEN DÜŞÜNÜR. KİRLİ İŞ AMA SİZ KİRLENMEYİ SEVERSİNİZ, DEĞİL Mİ?",
["Evet. Ee... Bunları sana hangi salak öğretti?"] = "EVET. EE... BUNLARI SANA HANGİ SALAK ÖĞRETTİ?",
["Evet. Evet. Tamam, doğru görünüyor. İyi günler."] = "EVET. EVET. TAMAM, DOĞRU GÖRÜNÜYOR. İYİ GÜNLER.",
["Evet. Kasa Dairesi! Bu iyi. Bu çok iyi!"] = "EVET. KASA DAİRESİ! BU İYİ. BU ÇOK İYİ!",
["Evet. Kesinlikle."] = "EVET. KESİNLİKLE.",
["Evet. Motele saldırı gibi bir şey. Umarım Yuri kurtulmuştur."] = "EVET. MOTELE SALDIRI GİBİ BİR ŞEY. UMARIM YURİ KURTULMUŞTUR.",
["Evet. O Kral'dı ama ben de bildiğin Ceasar'dım, anlıyor musun?"] = "EVET. O KRAL'DI AMA BEN DE BİLDİĞİN CEASAR'DIM, ANLIYOR MUSUN?",
["Evet. Pek de plana göre gitmedi, değil mi? Ama işi yine de bitirdik. Malı hemen elden çıkaracağım. Paramızı alır almaz bu işi getiren aptalla bağları koparıyorum. Ne olduğunu, o paralı askerlerin kim olduğunu öğrenmeliyiz. İçimden bir ses bu işin mezarından kalkıp peşimize düşeceğini söylüyor."] = "EVET. PEK DE PLANA GÖRE GİTMEDİ, DEĞİL Mİ? AMA İŞİ YİNE DE BİTİRDİK. MALI HEMEN ELDEN ÇIKARACAĞIM. PARAMIZI ALIR ALMAZ BU İŞİ GETİREN APTALLA BAĞLARI KOPARIYORUM. NE OLDUĞUNU, O PARALI ASKERLERİN KİM OLDUĞUNU ÖĞRENMELİYİZ. İÇİMDEN BİR SES BU İŞİN MEZARINDAN KALKIP PEŞİMİZE DÜŞECEĞİNİ SÖYLÜYOR.",
["Evet. İyi çalışır."] = "EVET. İYİ ÇALIŞIR.",
["Evet. İşe yarıyor. İçine biraz daha lazım. Yüklemeye devam."] = "EVET. İŞE YARIYOR. İÇİNE BİRAZ DAHA LAZIM. YÜKLEMEYE DEVAM.",
["Evet... Artık herkes Payday Gang ekibinden yardım istiyor gibi. Vlad, Anavatandaki maceramızı bir şekilde duyan kuzenine yardım etmemizi istiyor. Şimdiye kadar bize iyi davrandı. Hazırsanız neden ne diyeceğini dinlemeyelim? Ya da daha... yağlı bir iş isterseniz, tatil neşesinin yolunu göstermemiz gereken motorcularla dolu bir depodan da söz etti. Size kalmış çocuklar."] = "EVET... ARTIK HERKES PAYDAY GANG EKİBİNDEN YARDIM İSTİYOR GİBİ. VLAD, ANAVATANDAKİ MACERAMIZI BİR ŞEKİLDE DUYAN KUZENİNE YARDIM ETMEMİZİ İSTİYOR. ŞİMDİYE KADAR BİZE İYİ DAVRANDI. HAZIRSANIZ NEDEN NE DİYECEĞİNİ DİNLEMEYELİM? YA DA DAHA... YAĞLI BİR İŞ İSTERSENİZ, TATİL NEŞESİNİN YOLUNU GÖSTERMEMİZ GEREKEN MOTORCULARLA DOLU BİR DEPODAN DA SÖZ ETTİ. SİZE KALMIŞ ÇOCUKLAR.",
["Evet... Asit, tuz ruhu."] = "EVET... ASİT, TUZ RUHU.",
["Evet... Ben... Bilmiyorum... Büyük bir silah olabilir."] = "EVET... BEN... BİLMİYORUM... BÜYÜK BİR SİLAH OLABİLİR.",
["Evet... Küçük papağanlar gibi kumar oynayın."] = "EVET... KÜÇÜK PAPAĞANLAR GİBİ KUMAR OYNAYIN.",
["Evet?"] = "EVET?",
["Evet? Yok dostum, burada bir şey olmuyor. Ortalık ölü."] = "EVET? YOK DOSTUM, BURADA BİR ŞEY OLMUYOR. ORTALIK ÖLÜ.",
["Evi Boşaltmak"] = "EVİ BOŞALTMAK",
["Evi Temizle"] = "EVİ TEMİZLE",
["Evi açmalısın. Kapı ve pencereleri kontrol eden düğmeyi bul."] = "EVİ AÇMALISIN. KAPI VE PENCERELERİ KONTROL EDEN DÜĞMEYİ BUL.",
["Evin başının olduğu yerdir. Neden herkesten daha iri, daha iyi ve daha belalı olduğunu dünyaya göster. Teksas’a kimsenin bulaşmamasının sebebi sensin."] = "EVİN BAŞININ OLDUĞU YERDİR. NEDEN HERKESTEN DAHA İRİ, DAHA İYİ VE DAHA BELALI OLDUĞUNU DÜNYAYA GÖSTER. TEKSAS’A KİMSENİN BULAŞMAMASININ SEBEBİ SENSİN.",
["Evin elektriğini kestiler! Işıklar söndü."] = "EVİN ELEKTRİĞİNİ KESTİLER! IŞIKLAR SÖNDÜ.",
["Evin içindeler!"] = "EVİN İÇİNDELER!",
["Evin içine gir"] = "EVİN İÇİNE GİR",
["Evin kalanını açan bir şalter falan olmalı. Bulmaya çalışın."] = "EVİN KALANINI AÇAN BİR ŞALTER FALAN OLMALI. BULMAYA ÇALIŞIN.",
["Evin kalanını açmamız gerek. Bir yerde şalter olmalı."] = "EVİN KALANINI AÇMAMIZ GEREK. BİR YERDE ŞALTER OLMALI.",
["Evin yakınında bir yerde dizüstü bilgisayar olmalı. USB belleği ona takın."] = "EVİN YAKININDA BİR YERDE DİZÜSTÜ BİLGİSAYAR OLMALI. USB BELLEĞİ ONA TAKIN.",
["Evinde böyle bir yer yaptıracak kadar sikik bir egon olması lazım. Vlad daha sade yaşamayı sever."] = "EVİNDE BÖYLE BİR YER YAPTIRACAK KADAR SİKİK BİR EGON OLMASI LAZIM. VLAD DAHA SADE YAŞAMAYI SEVER.",
["Evine girmenin bir yolunu bul ve sunucu odasına ulaş"] = "EVİNE GİRMENİN BİR YOLUNU BUL VE SUNUCU ODASINA ULAŞ",
["Evinin bir yerine \"mabet\" adını nasıl bir \"kibirli göt\" verir?"] = "EVİNİN BİR YERİNE \"MABET\" ADINI NASIL BİR \"KİBİRLİ GÖT\" VERİR?",
["Evinize gidin piçler! Buraya giremezsiniz!"] = "EVİNİZE GİDİN PİÇLER! BURAYA GİREMEZSİNİZ!",
["Evlat, altmışa kadar sayana dek onları bu telefona getireceksin. Yoksa elimdeki her memuru gönderip götünü CTF'ye sürükletirim."] = "EVLAT, ALTMIŞA KADAR SAYANA DEK ONLARI BU TELEFONA GETİRECEKSİN. YOKSA ELİMDEKİ HER MEMURU GÖNDERİP GÖTÜNÜ CTF'YE SÜRÜKLETİRİM.",
["Evlat, onları bu telefona getirmen için tam iki dakikan var. Yoksa müsait bütün lanet üniformalıları hemen gönderiyorum."] = "EVLAT, ONLARI BU TELEFONA GETİRMEN İÇİN TAM İKİ DAKİKAN VAR. YOKSA MÜSAİT BÜTÜN LANET ÜNİFORMALILARI HEMEN GÖNDERİYORUM.",
["Evlat, onları telefona getirmek için sana üç dakika veriyorum. Yoksa polisi oyalamaktan işlem yaparım."] = "EVLAT, ONLARI TELEFONA GETİRMEK İÇİN SANA ÜÇ DAKİKA VERİYORUM. YOKSA POLİSİ OYALAMAKTAN İŞLEM YAPARIM.",
