["Evrim"] = "EVRİM",
["Evsiz olabilirim ama en azından fena bir bıçağım var."] = "EVSİZ OLABİLİRİM AMA EN AZINDAN FENA BİR BIÇAĞIM VAR.",
["Ex-Presidents, en cüretkâr soygun ekiplerinden biridir. Büyük riskler alan silah arkadaşlarıdır. Kendi ölümlülüklerinden korkmamaları onları bir araya getirmiş ve bu kadar başarılı kılmıştır."] = "EX-PRESİDENTS, EN CÜRETKÂR SOYGUN EKİPLERİNDEN BİRİDİR. BÜYÜK RİSKLER ALAN SİLAH ARKADAŞLARIDIR. KENDİ ÖLÜMLÜLÜKLERİNDEN KORKMAMALARI ONLARI BİR ARAYA GETİRMİŞ VE BU KADAR BAŞARILI KILMIŞTIR.",
["Exterminator film serisinin zaman yolculuğu yapan ikonik siborg yıldızı. İlk filmde, gelecekteki isyanın liderinin annesini öldürmek için gönderilmişti; kadın, aynı zamanda kendi babası da olan oğlunun bıraktığı çipi çalmadan önce... Geçmişte. \"Dönüşümü bekleyin\" repliğini ifadesiz bir suratla söylemesiyle tanınır."] = "EXTERMİNATOR FİLM SERİSİNİN ZAMAN YOLCULUĞU YAPAN İKONİK SİBORG YILDIZI. İLK FİLMDE, GELECEKTEKİ İSYANIN LİDERİNİN ANNESİNİ ÖLDÜRMEK İÇİN GÖNDERİLMİŞTİ; KADIN, AYNI ZAMANDA KENDİ BABASI DA OLAN OĞLUNUN BIRAKTIĞI ÇİPİ ÇALMADAN ÖNCE... GEÇMİŞTE. \"DÖNÜŞÜMÜ BEKLEYİN\" REPLİĞİNİ İFADESİZ BİR SURATLA SÖYLEMESİYLE TANINIR.",
["Eyvah, Commissar'ın helikopteri bir ısırık daha almak için dönmüş gibi."] = "EYVAH, COMMİSSAR'IN HELİKOPTERİ BİR ISIRIK DAHA ALMAK İÇİN DÖNMÜŞ GİBİ.",
["Eyvah, geliyorlar!"] = "EYVAH, GELİYORLAR!",
["Eyvah, meğer doğru malzeme bu değilmiş."] = "EYVAH, MEĞER DOĞRU MALZEME BU DEĞİLMİŞ.",
["Eyvah. Bunu yakmadığını öğrenirse Vlad çok kızacak. Ama bu mesajı özel yapan ne? Birden fazla tarafa oynadığı sır değil..."] = "EYVAH. BUNU YAKMADIĞINI ÖĞRENİRSE VLAD ÇOK KIZACAK. AMA BU MESAJI ÖZEL YAPAN NE? BİRDEN FAZLA TARAFA OYNADIĞI SIR DEĞİL...",
["Eyvah. Bunu çok gürültü çıkarmadan açamayacaksınız."] = "EYVAH. BUNU ÇOK GÜRÜLTÜ ÇIKARMADAN AÇAMAYACAKSINIZ.",
["Eziciler"] = "EZİCİLER",
["Ezilen"] = "EZİLEN",
["Ezilenlerin ritmi. Şehir içinin gürültüsünde sesini duyurmaya çalışan sokak şairlerinin düşüncelerinden doğan vahşi bir öfke. Gettonun sesleri sonsuza dek yankılanacak; toplumsal hapishanenin duvarları yıkılıp yeni bir günün kapılarını açacak."] = "EZİLENLERİN RİTMİ. ŞEHİR İÇİNİN GÜRÜLTÜSÜNDE SESİNİ DUYURMAYA ÇALIŞAN SOKAK ŞAİRLERİNİN DÜŞÜNCELERİNDEN DOĞAN VAHŞİ BİR ÖFKE. GETTONUN SESLERİ SONSUZA DEK YANKILANACAK; TOPLUMSAL HAPİSHANENİN DUVARLARI YIKILIP YENİ BİR GÜNÜN KAPILARINI AÇACAK.",
["Eğil ve Siper Al"] = "EĞİL VE SİPER AL",
["Eğitilmemiş Electarodent’i tatlı havuçları kemirirken ya da Alp çayırlarında koşup oynarken bulabilirsin. Ama tam eğitimli bir Electarodent genellikle Bernetti 9’ları kuşanıp Skulldozer’ların yüz siperlerini kemirirken görülür."] = "EĞİTİLMEMİŞ ELECTARODENT’İ TATLI HAVUÇLARI KEMİRİRKEN YA DA ALP ÇAYIRLARINDA KOŞUP OYNARKEN BULABİLİRSİN. AMA TAM EĞİTİMLİ BİR ELECTARODENT GENELLİKLE BERNETTI 9’LARI KUŞANIP SKULLDOZER’LARIN YÜZ SİPERLERİNİ KEMİRİRKEN GÖRÜLÜR.",
["Eğitim Sayesinde"] = "EĞİTİM SAYESİNDE",
["Eğitimde Daha Kolaydı..."] = "EĞİTİMDE DAHA KOLAYDI...",
["Eğlenceliydi!"] = "EĞLENCELİYDİ!",
