["FBI hâlâ uyuyor. Böyle devam edin çocuklar. Ganimeti oradan çıkarın..."] = "FBI HÂLÂ UYUYOR. BÖYLE DEVAM EDİN ÇOCUKLAR. GANİMETİ ORADAN ÇIKARIN...",
["FBI istihbarat sunucularında aramayı sürdürebilmesi için şifreleme anahtarlarını Hoxton’a getir."] = "FBI İSTİHBARAT SUNUCULARINDA ARAMAYI SÜRDÜREBİLMESİ İÇİN ŞİFRELEME ANAHTARLARINI HOXTON’A GETİR.",
["FBI karmakarışık. Bir sürü kişi patronunun odasına çağrılmak üzere. Mendoza'lar felç oldu, biz de paramızı almak üzereyiz. Güzel yaktınız millet."] = "FBI KARMAKARIŞIK. BİR SÜRÜ KİŞİ PATRONUNUN ODASINA ÇAĞRILMAK ÜZERE. MENDOZA'LAR FELÇ OLDU, BİZ DE PARAMIZI ALMAK ÜZEREYİZ. GÜZEL YAKTINIZ MİLLET.",
["FBI kaybetti, biz kazandık. Kazanmayı severim. Kalashnikov'lar artık Vlad'ın ordusunda. Vlad'ın parasıyla kutlayın dostlar."] = "FBI KAYBETTİ, BİZ KAZANDIK. KAZANMAYI SEVERİM. KALASHNİKOV'LAR ARTIK VLAD'IN ORDUSUNDA. VLAD'IN PARASIYLA KUTLAYIN DOSTLAR.",
["FBI malikâneye bir panik odası kurmuş. Hainin orada saklandığına bahse girerim. Bulun. Sonra içeri nasıl gireceğimizi düşünürüz!"] = "FBI MALİKÂNEYE BİR PANİK ODASI KURMUŞ. HAİNİN ORADA SAKLANDIĞINA BAHSE GİRERİM. BULUN. SONRA İÇERİ NASIL GİRECEĞİMİZİ DÜŞÜNÜRÜZ!",
["FBI merkezini arayın. Konuşmayı ben yaparım."] = "FBI MERKEZİNİ ARAYIN. KONUŞMAYI BEN YAPARIM.",
["FBI müdürüne yakınsınız. Parmağınızı tetikten çekin, canlı lazım olabilir."] = "FBI MÜDÜRÜNE YAKINSINIZ. PARMAĞINIZI TETİKTEN ÇEKİN, CANLI LAZIM OLABİLİR.",
["FBI ofis binasına girmenin bir yolunu bul"] = "FBI OFİS BİNASINA GİRMENİN BİR YOLUNU BUL",
["FBI ofislerine baskın yaparken aldığın küçük bir hatıra."] = "FBI OFİSLERİNE BASKIN YAPARKEN ALDIĞIN KÜÇÜK BİR HATIRA.",
["FBI peşimizde! Silahları kaldırın! O kokaini kaybetmeyin!"] = "FBI PEŞİMİZDE! SİLAHLARI KALDIRIN! O KOKAİNİ KAYBETMEYİN!",
["FBI sistemine sız."] = "FBI SİSTEMİNE SIZ.",
["FBI sizinle ilgilenecek, bana güvenin Bay Sturr."] = "FBI SİZİNLE İLGİLENECEK, BANA GÜVENİN BAY STURR.",
["FBI ve Mendoza'lar şimdi telaş içinde. Zayıfladılar ama ölmediler. Onu sonra halletmemiz gerekecek. Haberleşiriz."] = "FBI VE MENDOZA'LAR ŞİMDİ TELAŞ İÇİNDE. ZAYIFLADILAR AMA ÖLMEDİLER. ONU SONRA HALLETMEMİZ GEREKECEK. HABERLEŞİRİZ.",
["FBI ve rakip kartelimiz Mendoza'ların D.C.'deki kokain tedarikimize saldırdığını biliyoruz. Bu nakille gitmenizi ve güvenliğini sağlamanızı istiyoruz. Limandaki teknemize ulaştığından emin olun."] = "FBI VE RAKİP KARTELİMİZ MENDOZA'LARIN D.C.'DEKİ KOKAİN TEDARİKİMİZE SALDIRDIĞINI BİLİYORUZ. BU NAKİLLE GİTMENİZİ VE GÜVENLİĞİNİ SAĞLAMANIZI İSTİYORUZ. LİMANDAKİ TEKNEMİZE ULAŞTIĞINDAN EMİN OLUN.",
["FBI Şefini Panik Odasına Götür"] = "FBI ŞEFİNİ PANİK ODASINA GÖTÜR",
["FBI şefi konumunuza yakın görünüyor. Öldürmeyin, işimize yarayabilir."] = "FBI ŞEFİ KONUMUNUZA YAKIN GÖRÜNÜYOR. ÖLDÜRMEYİN, İŞİMİZE YARAYABİLİR.",
["FBI şefini Panik Odasının kapısına götürerek retina tarayıcısını aş."] = "FBI ŞEFİNİ PANİK ODASININ KAPISINA GÖTÜREREK RETİNA TARAYICISINI AŞ.",
["FBI şefini bul ve etkisiz hâle getir"] = "FBI ŞEFİNİ BUL VE ETKİSİZ HÂLE GETİR",
["FBI'a Hükmetmek"] = "FBI'A HÜKMETMEK",
["FBI'a ve orospuluk yapan Mendoza'lara açık bir mesaj göndermek istiyorum. Katkıda bulunabilirsiniz."] = "FBI'A VE OROSPULUK YAPAN MENDOZA'LARA AÇIK BİR MESAJ GÖNDERMEK İSTİYORUM. KATKIDA BULUNABİLİRSİNİZ.",
["FBI'a zorla girdiğimize inanamıyorum. İçeri girin millet; sessizce. Lütfen."] = "FBI'A ZORLA GİRDİĞİMİZE İNANAMIYORUM. İÇERİ GİRİN MİLLET; SESSİZCE. LÜTFEN.",
["FBI'da bana iyilik borcu olan eski bir tanıdığım, kullanmanız için bir dizüstü bilgisayarı ayarladı. Hangisi olduğunu beyaz tahtada işaretleyeceğini söyledi. Bulabilir misiniz, bakın."] = "FBI'DA BANA İYİLİK BORCU OLAN ESKİ BİR TANIDIĞIM, KULLANMANIZ İÇİN BİR DİZÜSTÜ BİLGİSAYARI AYARLADI. HANGİSİ OLDUĞUNU BEYAZ TAHTADA İŞARETLEYECEĞİNİ SÖYLEDİ. BULABİLİR MİSİNİZ, BAKIN.",
["FBI'daki bir bağlantım mekâna casus kameralar döşedi, dışarıya da gözetim dronları yerleştirdi. Çatıdaki cihazla onları kontrol edebilirsiniz."] = "FBI'DAKİ BİR BAĞLANTIM MEKÂNA CASUS KAMERALAR DÖŞEDİ, DIŞARIYA DA GÖZETİM DRONLARI YERLEŞTİRDİ. ÇATIDAKİ CİHAZLA ONLARI KONTROL EDEBİLİRSİNİZ.",
["FBI'daki eski bir dostumun bana borcu vardı, bize bir dizüstü bilgisayar ayarladı. Yerini bir beyaz tahtaya işaretleyeceğini söyledi. Gidip bulun."] = "FBI'DAKİ ESKİ BİR DOSTUMUN BANA BORCU VARDI, BİZE BİR DİZÜSTÜ BİLGİSAYAR AYARLADI. YERİNİ BİR BEYAZ TAHTAYA İŞARETLEYECEĞİNİ SÖYLEDİ. GİDİP BULUN.",
["FBI'daki eski bir... dostumun bana borcu vardı. Bizim için bir dizüstü hazırlattım. Yerini oralarda bir beyaz tahtada gizleyecekti."] = "FBI'DAKİ ESKİ BİR... DOSTUMUN BANA BORCU VARDI. BİZİM İÇİN BİR DİZÜSTÜ HAZIRLATTIM. YERİNİ ORALARDA BİR BEYAZ TAHTADA GİZLEYECEKTİ.",
["FBI'ın ana istihbarat sunucularının bulunduğu Operasyon Odasını bul."] = "FBI'IN ANA İSTİHBARAT SUNUCULARININ BULUNDUĞU OPERASYON ODASINI BUL.",
["FBI'ın en çok arananları. Siz de listeye gireceksiniz. Şu lanet sunucuyu alın artık!"] = "FBI'IN EN ÇOK ARANANLARI. SİZ DE LİSTEYE GİRECEKSİNİZ. ŞU LANET SUNUCUYU ALIN ARTIK!",
["FBI'ın geçici ofisi sokağın karşısında. Gizlice girin, sunucu odalarına erişmemi sağlayın. Etrafta Mendoza'larla ilgili başka ne bilgi var, bakın."] = "FBI'IN GEÇİCİ OFİSİ SOKAĞIN KARŞISINDA. GİZLİCE GİRİN, SUNUCU ODALARINA ERİŞMEMİ SAĞLAYIN. ETRAFTA MENDOZA'LARLA İLGİLİ BAŞKA NE BİLGİ VAR, BAKIN.",
["FBI'ın güvenli evi bu. Bakalım gerçekten ne kadar güvenliymiş."] = "FBI'IN GÜVENLİ EVİ BU. BAKALIM GERÇEKTEN NE KADAR GÜVENLİYMİŞ.",
["FBI'ın güvenli evinde bir yerdeki panik odasını bul. Hain içeride tutuluyor."] = "FBI'IN GÜVENLİ EVİNDE BİR YERDEKİ PANİK ODASINI BUL. HAİN İÇERİDE TUTULUYOR.",
["FBI'ın güvenli evinin dış çitini aş. Çitte zayıf bir nokta bul veya kapılardan birini aç."] = "FBI'IN GÜVENLİ EVİNİN DIŞ ÇİTİNİ AŞ. ÇİTTE ZAYIF BİR NOKTA BUL VEYA KAPILARDAN BİRİNİ AÇ.",
["FBI'ın sana karşı kullanacağı kanıtları bul ve güvenceye al. Evin çeşitli yerlerine dağılmış olmalılar."] = "FBI'IN SANA KARŞI KULLANACAĞI KANITLARI BUL VE GÜVENCEYE AL. EVİN ÇEŞİTLİ YERLERİNE DAĞILMIŞ OLMALILAR.",
["FBI, Payday Gang için geldiğinde palyaçolar karşılık verdi. Federalleri birden fazla kez aptal durumuna düşürdüler ama bunun için çetenin siyaset dünyasına bulaşması gerekti. Böylece güçlü dostlar... ve sayısız güçlü düşman kazandılar."] = "FBI, PAYDAY GANG İÇİN GELDİĞİNDE PALYAÇOLAR KARŞILIK VERDİ. FEDERALLERİ BİRDEN FAZLA KEZ APTAL DURUMUNA DÜŞÜRDÜLER AMA BUNUN İÇİN ÇETENİN SİYASET DÜNYASINA BULAŞMASI GEREKTİ. BÖYLECE GÜÇLÜ DOSTLAR... VE SAYISIZ GÜÇLÜ DÜŞMAN KAZANDILAR.",
["FIRST WORLD BANK soygununda C4 yerleştiren bir kolluk görevlisini Zor veya daha yüksek zorlukta yen. Bu Meydan Okuma için soygunu başından itibaren oynamış olmalısın."] = "FIRST WORLD BANK SOYGUNUNDA C4 YERLEŞTİREN BİR KOLLUK GÖREVLİSİNİ ZOR VEYA DAHA YÜKSEK ZORLUKTA YEN. BU MEYDAN OKUMA İÇİN SOYGUNU BAŞINDAN İTİBAREN OYNAMIŞ OLMALISIN.",
["FIRST WORLD BANK soygunundaki tüm kameraları silahlarınızı çektikten sonraki 10 saniye içinde yok et. Bu Meydan Okuma için soygunu başından itibaren oynamış olmalısın."] = "FIRST WORLD BANK SOYGUNUNDAKİ TÜM KAMERALARI SİLAHLARINIZI ÇEKTİKTEN SONRAKİ 10 SANİYE İÇİNDE YOK ET. BU MEYDAN OKUMA İÇİN SOYGUNU BAŞINDAN İTİBAREN OYNAMIŞ OLMALISIN.",
["FIRST WORLD BANK soygununu OVERKILL 145+ zorlukta tamamla. Bu Meydan Okuma için soygunu başından itibaren oynamış olmalısın."] = "FIRST WORLD BANK SOYGUNUNU OVERKILL 145+ ZORLUKTA TAMAMLA. BU MEYDAN OKUMA İÇİN SOYGUNU BAŞINDAN İTİBAREN OYNAMIŞ OLMALISIN.",
